      "notification.permission.titleSkillShell": "\u0647\u0644 \u062A\u0631\u064A\u062F \u062A\u0634\u063A\u064A\u0644 \u0623\u0648\u0627\u0645\u0631 \u0627\u0644\u0635\u062F\u0641\u0629 \u0645\u0646 \u0627\u0644\u0645\u0647\u0627\u0631\u0629 \xAB{{skill}}\xBB\u061F",
      "notification.permission.titleSandboxEscalation": "\u0627\u0644\u062A\u0634\u063A\u064A\u0644 \u062E\u0627\u0631\u062C \u0627\u0644\u0628\u064A\u0626\u0629 \u0627\u0644\u0645\u0639\u0632\u0648\u0644\u0629\u061F",
      "notification.permission.descriptionSandboxEscalation": "\u064A\u064F\u0634\u063A\u0651\u0644 \u0647\u0630\u0627 \u0627\u0644\u0623\u0645\u0631 \u0628\u0627\u0644\u0643\u0627\u0645\u0644 \u0645\u0639 \u0625\u0632\u0627\u0644\u0629 \u0642\u064A\u0648\u062F \u0646\u0638\u0627\u0645 \u0627\u0644\u0645\u0644\u0641\u0627\u062A \u0648\u0627\u0644\u0634\u0628\u0643\u0629\u060C \u0644\u0647\u0630\u0627 \u0627\u0644\u0623\u0645\u0631 \u0641\u0642\u0637. \u064A\u062C\u0628 \u0623\u0646 \u064A\u0643\u062A\u0628 Git \u0641\u064A .git\u060C \u0648\u0647\u0648 \u0644\u0644\u0642\u0631\u0627\u0621\u0629 \u0641\u0642\u0637 \u062F\u0627\u062E\u0644 \u0627\u0644\u0628\u064A\u0626\u0629 \u0627\u0644\u0645\u0639\u0632\u0648\u0644\u0629 \u0648\u064A\u0642\u0639 \u062E\u0627\u0631\u062C \u0634\u062C\u0631\u0629 \u0627\u0644\u0639\u0645\u0644 \u0641\u064A worktree \u0645\u0631\u062A\u0628\u0637. \u0644\u0627 \u062A\u0648\u0627\u0641\u0642 \u0642\u0648\u0627\u0639\u062F \u0633\u0645\u0627\u062D Bash \u0648\u0627\u0644\u0645\u0648\u0627\u0641\u0642\u0629 \u0627\u0644\u062A\u0644\u0642\u0627\u0626\u064A\u0629 \u0639\u0644\u0649 \u0647\u0630\u0627 \u0627\u0644\u0637\u0644\u0628 \u062A\u0644\u0642\u0627\u0626\u064A\u0627\u064B \u0623\u0628\u062F\u0627\u064B.",
