      "settings.notifications.os.description": "\u0639\u0631\u0636 \u062A\u0646\u0628\u064A\u0647\u0627\u062A \u0625\u0634\u0639\u0627\u0631\u0627\u062A \u0646\u0638\u0627\u0645 \u0627\u0644\u062A\u0634\u063A\u064A\u0644 \u0627\u0644\u0623\u0635\u0644\u064A\u0629 \u0639\u0646\u062F \u0627\u0643\u062A\u0645\u0627\u0644 \u0645\u0647\u0645\u0629 Kilo \u0623\u0648 \u0627\u0644\u062D\u0627\u062C\u0629 \u0625\u0644\u0649 \u0631\u062F\u0651\u0643 \u0628\u064A\u0646\u0645\u0627 \u064A\u0643\u0648\u0646 VS Code \u063A\u064A\u0631 \u0646\u0634\u0637.",
