      "settings.notifications.sound.default": "\u0627\u0641\u062A\u0631\u0627\u0636\u064A",
      "settings.notifications.sound.system": "\u0627\u0644\u0646\u0638\u0627\u0645",
      "settings.notifications.sound.description": "\u064A\u0633\u062A\u062E\u062F\u0645 \u0627\u0644\u062E\u064A\u0627\u0631 \u0627\u0644\u0627\u0641\u062A\u0631\u0627\u0636\u064A \u0623\u0635\u0648\u0627\u062A\u064B\u0627 \u0645\u062E\u062A\u0644\u0641\u0629 \u0639\u0646\u062F \u0627\u0644\u0627\u0643\u062A\u0645\u0627\u0644 \u0623\u0648 \u0627\u0644\u062D\u0627\u062C\u0629 \u0625\u0644\u0649 \u0631\u062F\u0651\u0643 \u0623\u0648 \u062D\u062F\u0648\u062B \u062E\u0637\u0623. \u062A\u0633\u062A\u062E\u062F\u0645 \u0627\u0644\u062E\u064A\u0627\u0631\u0627\u062A \u0627\u0644\u0623\u062E\u0631\u0649 \u0635\u0648\u062A\u064B\u0627 \u0648\u0627\u062D\u062F\u064B\u0627 \u0644\u062C\u0645\u064A\u0639 \u0627\u0644\u0623\u062D\u062F\u0627\u062B.",
