      "settings.experimental.batch.title": "\u0623\u062F\u0627\u0629 \u062F\u0641\u0639\u064A\u0629",
      "settings.experimental.batch.description": "\u062A\u0645\u0643\u064A\u0646 \u0627\u0644\u0645\u0639\u0627\u0644\u062C\u0629 \u0627\u0644\u062F\u0641\u0639\u064A\u0629 \u0644\u0627\u0633\u062A\u062F\u0639\u0627\u0621\u0627\u062A \u0627\u0644\u0623\u062F\u0648\u0627\u062A",
