      "settings.agentBehaviour.editMode.back": "\u0627\u0644\u0639\u0648\u062F\u0629 \u0625\u0644\u0649 \u0627\u0644\u0642\u0627\u0626\u0645\u0629",
      "settings.agentBehaviour.editMode.native": "\u0647\u0630\u0627 \u0648\u0636\u0639 \u0645\u0636\u0645\u0646. \u0644\u0627 \u064A\u0645\u0643\u0646 \u062A\u063A\u064A\u064A\u0631 \u062A\u0639\u0631\u064A\u0641\u0647 \u0627\u0644\u0623\u0633\u0627\u0633\u064A\u060C \u0648\u0644\u0643\u0646 \u064A\u0645\u0643\u0646\u0643 \u062A\u0643\u0648\u064A\u0646 \u0627\u0644\u062A\u062C\u0627\u0648\u0632\u0627\u062A \u0623\u062F\u0646\u0627\u0647.",
      "settings.agentBehaviour.editMode.promptOverride": "\u062A\u062C\u0627\u0648\u0632 \u0645\u0648\u062C\u0647 \u0645\u062E\u0635\u0635 \u0644\u0647\u0630\u0627 \u0627\u0644\u0648\u0636\u0639 \u0627\u0644\u0645\u062F\u0645\u062C",
      "settings.agentBehaviour.badge.subagent": "\u0648\u0643\u064A\u0644 \u0641\u0631\u0639\u064A",
      "settings.agentBehaviour.perAgentPermissions.title": "\u0623\u0630\u0648\u0646\u0627\u062A \u0644\u0643\u0644 \u0648\u0643\u064A\u0644",
      "settings.agentBehaviour.perAgentPermissions.description": "\u062A\u0646\u0637\u0628\u0642 \u0647\u0630\u0647 \u0627\u0644\u0625\u0639\u062F\u0627\u062F\u0627\u062A \u0639\u0644\u0649 \u0647\u0630\u0627 \u0627\u0644\u0648\u0643\u064A\u0644 \u0627\u0644\u0645\u062E\u0635\u0635 \u0641\u0642\u0637. \u063A\u064A\u0651\u0631 \u0642\u064A\u0645\u0629 \u0625\u062D\u062F\u0649 \u0627\u0644\u0642\u0648\u0627\u0626\u0645 \u0627\u0644\u0645\u0646\u0633\u062F\u0644\u0629 \u0645\u0646 '\u0627\u0641\u062A\u0631\u0627\u0636\u064A' \u0644\u0625\u0646\u0634\u0627\u0621 \u062A\u062C\u0627\u0648\u0632\u060C \u0623\u0648 \u0627\u0633\u062A\u062E\u062F\u0645 '\u0625\u0636\u0627\u0641\u0629 \u0645\u0633\u0627\u0631' \u0623\u0648 '\u0625\u0636\u0627\u0641\u0629 \u0623\u0645\u0631' \u0644\u0644\u0627\u0633\u062A\u062B\u0646\u0627\u0621\u0627\u062A \u0627\u0644\u062E\u0627\u0635\u0629 \u0628\u0627\u0644\u0623\u062F\u0648\u0627\u062A.",
      "settings.agentBehaviour.permissions.title": "\u0627\u0644\u0623\u0630\u0648\u0646\u0627\u062A \u0627\u0644\u0645\u062D\u0633\u0648\u0628\u0629",
