      "settings.agentBehaviour.permissions.col.pattern": "\u0627\u0644\u0646\u0645\u0637",
      "settings.agentBehaviour.permissions.col.action": "\u0627\u0644\u0625\u062C\u0631\u0627\u0621",
      "settings.agentBehaviour.permissions.copy": "\u0646\u0633\u062E \u0627\u0644\u0623\u0630\u0648\u0646\u0627\u062A \u0643\u0640 JSON",
      "settings.agentBehaviour.permissions.hint": "\u064A\u062A\u0645 \u062A\u0642\u064A\u064A\u0645 \u0627\u0644\u0642\u0648\u0627\u0639\u062F \u0628\u0627\u0644\u062A\u0631\u062A\u064A\u0628 \u2014 \u0627\u0644\u0642\u0627\u0639\u062F\u0629 \u0627\u0644\u0645\u0637\u0627\u0628\u0642\u0629 \u0627\u0644\u0623\u062E\u064A\u0631\u0629 \u0647\u064A \u0627\u0644\u062A\u064A \u062A\u064F\u0637\u0628\u0642. \u0647\u0630\u0647 \u0647\u064A \u0645\u062C\u0645\u0648\u0639\u0629 \u0627\u0644\u0642\u0648\u0627\u0639\u062F \u0627\u0644\u0645\u062D\u0644\u0648\u0644\u0629 \u0645\u0646 \u062E\u0644\u0641\u064A\u0629 CLI.",
      "settings.agentBehaviour.removeAgent.title": "\u0625\u0632\u0627\u0644\u0629 \u0627\u0644\u0648\u0643\u064A\u0644",
      "settings.agentBehaviour.removeAgent.confirm": '\u0647\u0644 \u062A\u0631\u064A\u062F \u0625\u0632\u0627\u0644\u0629 \u0627\u0644\u0648\u0643\u064A\u0644 "{{name}}"\u061F \u0633\u064A\u0624\u062F\u064A \u0647\u0630\u0627 \u0625\u0644\u0649 \u062A\u0639\u0637\u064A\u0644\u0647 \u0639\u0646 \u0637\u0631\u064A\u0642 \u062A\u062D\u062F\u064A\u062B \u0627\u0644\u0625\u0639\u062F\u0627\u062F\u0627\u062A.',
      "settings.agentBehaviour.removeAgent.button": "\u0625\u0632\u0627\u0644\u0629",
      "settings.agentBehaviour.removeMcp.title": "\u0625\u0632\u0627\u0644\u0629 \u062E\u0627\u062F\u0645 MCP",
      "settings.agentBehaviour.removeMcp.confirm": '\u0647\u0644 \u062A\u0631\u064A\u062F \u0625\u0632\u0627\u0644\u0629 \u062E\u0627\u062F\u0645 MCP "{{name}}"\u061F \u0633\u064A\u0624\u062F\u064A \u0647\u0630\u0627 \u0625\u0644\u0649 \u0625\u0632\u0627\u0644\u062A\u0647 \u0645\u0646 \u0627\u0644\u0625\u0639\u062F\u0627\u062F\u0627\u062A.',
      "settings.agentBehaviour.removeMcp.bundleConfirm": '\u0625\u0632\u0627\u0644\u0629 \u062E\u0627\u062F\u0645 MCP "{{name}}" \u0648\u0645\u0647\u0627\u0631\u0627\u062A\u0647 \u0627\u0644\u0645\u0631\u0627\u0641\u0642\u0629\u061F \u0633\u064A\u0624\u062F\u064A \u0647\u0630\u0627 \u0625\u0644\u0649 \u0625\u0632\u0627\u0644\u0629 \u0627\u0644\u062E\u0627\u062F\u0645 \u0648\u0643\u0644 \u0645\u0647\u0627\u0631\u0629 \u064A\u0645\u0644\u0643\u0647\u0627 \u0647\u0630\u0627 \u0627\u0644\u062A\u062B\u0628\u064A\u062A \u0645\u0646 \u0627\u0644\u0645\u062A\u062C\u0631.',
