      "settings.agentBehaviour.editMcp.env.help": "\u0627\u0644\u0645\u062A\u063A\u064A\u0631\u0627\u062A \u0627\u0644\u062A\u064A \u064A\u062A\u0645 \u062A\u0645\u0631\u064A\u0631\u0647\u0627 \u0625\u0644\u0649 \u0639\u0645\u0644\u064A\u0629 \u062E\u0627\u062F\u0645 MCP.",
