      "settings.agentBehaviour.editMcp.oauth.help": "\u0627\u062A\u0631\u0643\u0647 \u0639\u0644\u0649 \u0627\u0644\u062A\u0644\u0642\u0627\u0626\u064A \u0625\u0644\u0627 \u0625\u0630\u0627 \u0643\u0627\u0646 \u0627\u0644\u062E\u0627\u062F\u0645 \u064A\u062A\u0637\u0644\u0628 \u0639\u0645\u064A\u0644\u0627\u064B \u0645\u0633\u062C\u0644\u0627\u064B \u0645\u0633\u0628\u0642\u064B\u0627. \u064A\u062A\u0645 \u062A\u062E\u0632\u064A\u0646 \u0633\u0631 \u0627\u0644\u0639\u0645\u064A\u0644 \u0641\u064A \u0645\u0644\u0641 \u062A\u0647\u064A\u0626\u0629 Kilo.",
