      "marketplace.remove.confirm": "\u0647\u0644 \u0623\u0646\u062A \u0645\u062A\u0623\u0643\u062F \u0623\u0646\u0643 \u062A\u0631\u064A\u062F \u0625\u0632\u0627\u0644\u0629 \u0647\u0630\u0627 \u0627\u0644\u0640 {{type}}\u061F \u0633\u064A\u0624\u062F\u064A \u0647\u0630\u0627 \u0625\u0644\u0649 \u0625\u0632\u0627\u0644\u062A\u0647 \u0645\u0646 \u062A\u0643\u0648\u064A\u0646 {{scope}} \u0627\u0644\u062E\u0627\u0635 \u0628\u0643.",
      "marketplace.remove.cancel": "\u0625\u0644\u063A\u0627\u0621",
      "marketplace.remove.mcp.skills": "\u064A\u0624\u062F\u064A \u0647\u0630\u0627 \u0623\u064A\u0636\u064B\u0627 \u0625\u0644\u0649 \u0625\u0632\u0627\u0644\u0629 \u0627\u0644\u0645\u0647\u0627\u0631\u0627\u062A \u0627\u0644\u0645\u0631\u0627\u0641\u0642\u0629 \u0627\u0644\u062A\u0627\u0628\u0639\u0629 \u0644\u0647\u0630\u0627 \u0627\u0644\u062A\u062B\u0628\u064A\u062A. \u064A\u062A\u0645 \u0627\u0644\u0627\u062D\u062A\u0641\u0627\u0638 \u0628\u0627\u0644\u0645\u0647\u0627\u0631\u0627\u062A \u0627\u0644\u0645\u062B\u0628\u062A\u0629 \u0628\u0634\u0643\u0644 \u0645\u0633\u062A\u0642\u0644.",
