      "provider.anaconda.state.noModel": "\u062F\u0631 Anaconda Desktop\u060C \u06CC\u06A9 \u0645\u062F\u0644 \u062A\u0648\u0644\u06CC\u062F \u0645\u062A\u0646 \u062F\u0627\u0646\u0644\u0648\u062F \u06A9\u0646\u06CC\u062F. \u062F\u0631 \u0635\u0648\u0631\u062A \u0627\u0645\u06A9\u0627\u0646 \u0645\u062F\u0644\u06CC \u0628\u0627 \u0642\u0627\u0628\u0644\u06CC\u062A \u0641\u0631\u0627\u062E\u0648\u0627\u0646\u06CC \u0627\u0628\u0632\u0627\u0631 \u0627\u0646\u062A\u062E\u0627\u0628 \u06A9\u0646\u06CC\u062F\u060C \u0633\u067E\u0633 \u0633\u0631\u0648\u0631 \u0622\u0646 \u0631\u0627 \u0631\u0627\u0647\u200C\u0627\u0646\u062F\u0627\u0632\u06CC \u06A9\u0646\u06CC\u062F.",
