      "prompt.action.sandbox.description.enabled": "\u0646\u0648\u0634\u062A\u0646\u200C\u0647\u0627 \u0628\u0647 \u067E\u0648\u0634\u0647\u200C\u0647\u0627\u06CC \u067E\u0631\u0648\u0698\u0647 \u0648 Kilo \u0645\u062D\u062F\u0648\u062F \u0634\u062F\u0647\u200C\u0627\u0646\u062F.",
      "prompt.action.sandbox.description.escalation": "\u0642\u0648\u0627\u0639\u062F \u0645\u062C\u0648\u0632 \u0648 \u062A\u0623\u06CC\u06CC\u062F \u062E\u0648\u062F\u06A9\u0627\u0631 \u062F\u0631 \u062F\u0627\u062E\u0644 sandbox \u0627\u0639\u0645\u0627\u0644 \u0645\u06CC\u200C\u0634\u0648\u0646\u062F. \u0641\u0631\u0645\u0627\u0646\u200C\u0647\u0627\u06CC\u06CC \u06A9\u0647 \u0628\u0627\u06CC\u062F \u0627\u0632 \u0622\u0646 \u062E\u0627\u0631\u062C \u0634\u0648\u0646\u062F \u0647\u0645\u06CC\u0634\u0647 \u0645\u06CC\u200C\u067E\u0631\u0633\u0646\u062F.",
      "prompt.action.sandbox.description.disabled": "\u0628\u0631\u0627\u06CC \u0645\u062D\u062F\u0648\u062F \u06A9\u0631\u062F\u0646 \u0646\u0648\u0634\u062A\u0646 \u062F\u0631 \u0633\u06CC\u0633\u062A\u0645 \u0641\u0627\u06CC\u0644 \u0648 \u062F\u0633\u062A\u0631\u0633\u06CC \u0628\u0647 \u0634\u0628\u06A9\u0647 \u06A9\u0644\u06CC\u06A9 \u06A9\u0646\u06CC\u062F.",
      "prompt.action.sandbox.description.disabledNetworkAllowed": "\u0628\u0631\u0627\u06CC \u0645\u062D\u062F\u0648\u062F \u06A9\u0631\u062F\u0646 \u0646\u0648\u0634\u062A\u0646 \u062F\u0631 \u0633\u06CC\u0633\u062A\u0645 \u0641\u0627\u06CC\u0644 \u06A9\u0644\u06CC\u06A9 \u06A9\u0646\u06CC\u062F. \u062F\u0633\u062A\u0631\u0633\u06CC \u0628\u0647 \u0634\u0628\u06A9\u0647 \u0637\u0628\u0642 \u062A\u0646\u0638\u06CC\u0645\u0627\u062A sandbox \u0634\u0645\u0627 \u0645\u062C\u0627\u0632 \u0627\u0633\u062A.",
      "prompt.action.enhanceDescription": "\u062F\u06A9\u0645\u0647 \xAB\u0628\u0647\u0628\u0648\u062F \u067E\u0631\u0627\u0645\u067E\u062A\xBB \u0628\u0627 \u0627\u0631\u0627\u0626\u0647 \u0632\u0645\u06CC\u0646\u0647 \u0628\u06CC\u0634\u062A\u0631\u060C \u062A\u0648\u0636\u06CC\u062D \u06CC\u0627 \u0628\u0627\u0632\u0646\u0648\u06CC\u0633\u06CC\u060C \u0628\u0647 \u0628\u0647\u062A\u0631 \u06A9\u0631\u062F\u0646 \u067E\u0631\u0627\u0645\u067E\u062A \u0634\u0645\u0627 \u06A9\u0645\u06A9 \u0645\u06CC\u200C\u06A9\u0646\u062F. \u06CC\u06A9 \u067E\u0631\u0627\u0645\u067E\u062A \u062A\u0627\u06CC\u067E \u06A9\u0646\u06CC\u062F \u0648 \u062F\u0648\u0628\u0627\u0631\u0647 \u0631\u0648\u06CC \u062F\u06A9\u0645\u0647 \u06A9\u0644\u06CC\u06A9 \u06A9\u0646\u06CC\u062F \u062A\u0627 \u0646\u062D\u0648\u0647 \u0639\u0645\u0644\u06A9\u0631\u062F \u0622\u0646 \u0631\u0627 \u0628\u0628\u06CC\u0646\u06CC\u062F.",
      "speechToText.tooltip.start": "\u0634\u0631\u0648\u0639 \u0648\u0631\u0648\u062F\u06CC \u0635\u0648\u062A\u06CC",
      "speechToText.tooltip.shortcut": "\u0628\u0631\u0627\u06CC \u0634\u0631\u0648\u0639 \u06CC\u0627 \u062A\u0648\u0642\u0641 \u0636\u0628\u0637\u060C \u0631\u0648\u06CC \u062F\u06A9\u0645\u0647 \u0636\u0631\u0628\u0647 \u0628\u0632\u0646\u06CC\u062F \u06CC\u0627 Cmd/Ctrl+K \u0631\u0627 \u0641\u0634\u0627\u0631 \u062F\u0647\u06CC\u062F\u061B \u0647\u0646\u06AF\u0627\u0645 \u0635\u062D\u0628\u062A \u062F\u06A9\u0645\u0647 \u0631\u0627 \u0646\u06AF\u0647 \u062F\u0627\u0631\u06CC\u062F \u0648 \u0633\u067E\u0633 \u0631\u0647\u0627 \u06A9\u0646\u06CC\u062F \u062A\u0627 \u06AF\u0641\u062A\u0627\u0631 \u0628\u0647 \u0645\u062A\u0646 \u062A\u0628\u062F\u06CC\u0644 \u0648 \u0627\u0631\u0633\u0627\u0644 \u0634\u0648\u062F.",
