      "speechToText.tooltip.stop": "\u062F\u0631 \u062D\u0627\u0644 \u0636\u0628\u0637. \u0628\u0631\u0627\u06CC \u062A\u0648\u0642\u0641 \u06A9\u0644\u06CC\u06A9 \u06A9\u0646\u06CC\u062F.",
      "speechToText.tooltip.transcribing": "\u062F\u0631 \u062D\u0627\u0644 \u0631\u0648\u0646\u0648\u06CC\u0633\u06CC... \u0628\u0631\u0627\u06CC \u0644\u063A\u0648 \u06A9\u0644\u06CC\u06A9 \u06A9\u0646\u06CC\u062F.",
