      "error.providerAuth.chatgpt.description": "\u062F\u0648\u0628\u0627\u0631\u0647 \u0628\u0627 ChatGPT \u0648\u0627\u0631\u062F \u0634\u0648\u06CC\u062F\u060C \u0633\u067E\u0633 \u067E\u06CC\u0627\u0645 \u062E\u0648\u062F \u0631\u0627 \u0645\u062C\u062F\u062F\u0627\u064B \u0627\u0631\u0633\u0627\u0644 \u06A9\u0646\u06CC\u062F \u062A\u0627 \u0627\u0632 \u0645\u062F\u0644\u200C\u0647\u0627\u06CC Codex \u0627\u0633\u062A\u0641\u0627\u062F\u0647 \u06A9\u0646\u06CC\u062F.",
      "provider.failure.unauthorized": "\u0627\u0639\u062A\u0628\u0627\u0631\u0646\u0627\u0645\u0647 \u0631\u062F \u0634\u062F (HTTP {{status}}). \u062F\u0648\u0628\u0627\u0631\u0647 \u0648\u0627\u0631\u062F \u0634\u0648\u06CC\u062F.",
