      "ui.permission.feedbackPlaceholder": "\u0628\u0647 Kilo \u0628\u06AF\u0648\u06CC\u06CC\u062F \u0686\u0647 \u06A9\u0627\u0631\u06CC \u0631\u0627 \u0645\u062A\u0641\u0627\u0648\u062A \u0627\u0646\u062C\u0627\u0645 \u062F\u0647\u062F",
