      "settings.aboutKiloCode.resetSettings.title": "\u0628\u0627\u0632\u0646\u0634\u0627\u0646\u06CC \u062A\u0646\u0638\u06CC\u0645\u0627\u062A",
      "settings.aboutKiloCode.resetSettings.description": "\u0627\u06CC\u0646 \u06AF\u0632\u06CC\u0646\u0647 \u0641\u0642\u0637 \u062A\u0646\u0638\u06CC\u0645\u0627\u062A \u0645\u062E\u0635\u0648\u0635 \u0627\u0641\u0632\u0648\u0646\u0647 VS Code \u0631\u0627 \u0628\u0647 \u0645\u0642\u0627\u062F\u06CC\u0631 \u067E\u06CC\u0634\u200C\u0641\u0631\u0636 \u0628\u0627\u0632\u0646\u0634\u0627\u0646\u06CC \u0645\u06CC\u200C\u06A9\u0646\u062F. \u062A\u0646\u0638\u06CC\u0645\u0627\u062A \u0645\u0634\u062A\u0631\u06A9 \u0628\u0627 CLI\u060C \u0645\u0627\u0646\u0646\u062F \u062D\u0627\u0644\u062A\u200C\u0647\u0627 \u0648 \u0642\u0648\u0627\u0646\u06CC\u0646 \u062A\u0623\u06CC\u06CC\u062F \u062E\u0648\u062F\u06A9\u0627\u0631\u060C \u062F\u0631 \u067E\u06CC\u06A9\u0631\u0628\u0646\u062F\u06CC CLI \u0630\u062E\u06CC\u0631\u0647 \u0645\u06CC\u200C\u0634\u0648\u0646\u062F \u0648 \u0628\u0627\u0632\u0646\u0634\u0627\u0646\u06CC \u0646\u062E\u0648\u0627\u0647\u0646\u062F \u0634\u062F.",
