      "settings.aboutKiloCode.importSettings.newerVersion": "\u0627\u06CC\u0646 \u0641\u0627\u06CC\u0644 \u0627\u0632 \u0646\u0633\u062E\u0647 \u062C\u062F\u06CC\u062F\u062A\u0631\u06CC \u0627\u0632 Kilo \u0635\u0627\u062F\u0631 \u0634\u062F\u0647 \u0627\u0633\u062A. \u0628\u0631\u062E\u06CC \u062A\u0646\u0638\u06CC\u0645\u0627\u062A \u0645\u0645\u06A9\u0646 \u0627\u0633\u062A \u0646\u0627\u062F\u06CC\u062F\u0647 \u06AF\u0631\u0641\u062A\u0647 \u0634\u0648\u0646\u062F.",
      "settings.aboutKiloCode.importSettings.success": "\u062A\u0646\u0638\u06CC\u0645\u0627\u062A \u0648\u0627\u0631\u062F \u0634\u062F. \u062A\u063A\u06CC\u06CC\u0631\u0627\u062A \u0628\u0627\u0644\u0627 \u0631\u0627 \u0628\u0631\u0631\u0633\u06CC \u06A9\u0646\u06CC\u062F\u060C \u0633\u067E\u0633 \u0631\u0648\u06CC \u0630\u062E\u06CC\u0631\u0647 \u06A9\u0644\u06CC\u06A9 \u06A9\u0646\u06CC\u062F.",
