      "settings.agentBehaviour.subtab.skills": "\u0645\u0647\u0627\u0631\u062A\u200C\u0647\u0627",
      "settings.browser.description": "\u067E\u06CC\u06A9\u0631\u0628\u0646\u062F\u06CC \u0627\u062A\u0648\u0645\u0627\u0633\u06CC\u0648\u0646 \u0645\u0631\u0648\u0631\u06AF\u0631 \u062F\u0627\u062E\u0644\u06CC \u0628\u0627 \u067E\u0634\u062A\u06CC\u0628\u0627\u0646\u06CC Playwright. Kilo \u0645\u06CC\u200C\u062A\u0648\u0627\u0646\u062F \u062F\u0631 \u062C\u0644\u0633\u0627\u062A \u0634\u0645\u0627 \u062F\u0631 \u0635\u0641\u062D\u0627\u062A \u0648\u0628 \u067E\u06CC\u0645\u0627\u06CC\u0634 \u06A9\u0646\u062F\u060C \u0628\u0627 \u0622\u0646\u200C\u0647\u0627 \u062A\u0639\u0627\u0645\u0644 \u062F\u0627\u0634\u062A\u0647 \u0628\u0627\u0634\u062F \u0648 \u0627\u0633\u06A9\u0631\u06CC\u0646\u200C\u0634\u0627\u062A \u0628\u06AF\u06CC\u0631\u062F.",
