      "settings.language.description": "\u0632\u0628\u0627\u0646 \u0631\u0627\u0628\u0637 \u06A9\u0627\u0631\u0628\u0631\u06CC Kilo Code \u0631\u0627 \u0627\u0646\u062A\u062E\u0627\u0628 \u06A9\u0646\u06CC\u062F. \xABAuto\xBB \u0627\u0632 \u0632\u0628\u0627\u0646 \u0646\u0645\u0627\u06CC\u0634\u06CC VS Code \u0634\u0645\u0627 \u0627\u0633\u062A\u0641\u0627\u062F\u0647 \u0645\u06CC\u200C\u06A9\u0646\u062F.",
