      "settings.autocomplete.smartKeybinding.description": "\u0627\u0632 \u06CC\u06A9 \u0645\u06CC\u0627\u0646\u0628\u0631 \u0647\u0648\u0634\u0645\u0646\u062F \u0628\u0631\u0627\u06CC \u0641\u0639\u0627\u0644\u200C\u0633\u0627\u0632\u06CC \u0648\u0638\u0627\u06CC\u0641 \u062F\u0631\u0648\u0646\u200C\u062E\u0637\u06CC \u0627\u0633\u062A\u0641\u0627\u062F\u0647 \u06A9\u0646",
