      "settings.notifications.sound.default": "\u067E\u06CC\u0634\u200C\u0641\u0631\u0636",
      "settings.notifications.sound.system": "\u0633\u06CC\u0633\u062A\u0645",
      "settings.notifications.sound.description": "\u067E\u06CC\u0634\u200C\u0641\u0631\u0636 \u0627\u0632 \u0635\u062F\u0627\u0647\u0627\u06CC \u0645\u062E\u062A\u0644\u0641 \u0628\u0631\u0627\u06CC \u062A\u06A9\u0645\u06CC\u0644\u060C \u0648\u0631\u0648\u062F\u06CC \u0648 \u062E\u0637\u0627\u0647\u0627 \u0627\u0633\u062A\u0641\u0627\u062F\u0647 \u0645\u06CC\u200C\u06A9\u0646\u062F. \u0633\u0627\u06CC\u0631 \u06AF\u0632\u06CC\u0646\u0647\u200C\u0647\u0627 \u0627\u0632 \u06CC\u06A9 \u0635\u062F\u0627 \u0628\u0631\u0627\u06CC \u0647\u0645\u0647 \u0631\u0648\u06CC\u062F\u0627\u062F\u0647\u0627 \u0627\u0633\u062A\u0641\u0627\u062F\u0647 \u0645\u06CC\u200C\u06A9\u0646\u0646\u062F.",
