      "settings.agentBehaviour.addMcp.args.help": "\u06CC\u06A9 \u0622\u0631\u06AF\u0648\u0645\u0627\u0646 \u062F\u0631 \u0647\u0631 \u062E\u0637. \u0645\u0633\u06CC\u0631\u0647\u0627\u06CC \u062F\u0627\u0631\u0627\u06CC \u0641\u0627\u0635\u0644\u0647 \u0639\u06CC\u0646\u0627\u064B \u062D\u0641\u0638 \u0645\u06CC\u200C\u0634\u0648\u0646\u062F.",
