      "settings.agentBehaviour.mcpEmpty": "\u0647\u06CC\u0686 \u0633\u0631\u0648\u0631 MCP \u067E\u06CC\u06A9\u0631\u0628\u0646\u062F\u06CC \u0646\u0634\u062F\u0647 \u0627\u0633\u062A. \u0633\u0631\u0648\u0631\u0647\u0627\u06CC MCP \u0631\u0627 \u062F\u0631 kilo2.json \u0627\u0636\u0627\u0641\u0647 \u06A9\u0646\u06CC\u062F\u060C \u06CC\u0627 \u0627\u0632 agent \u0628\u062E\u0648\u0627\u0647\u06CC\u062F \u0622\u0646\u200C\u0647\u0627 \u0631\u0627 \u0628\u0631\u0627\u06CC\u062A\u0627\u0646 \u0627\u0636\u0627\u0641\u0647 \u06A9\u0646\u062F.",
      "settings.agentBehaviour.workflows.description": "Workflow\u200C\u0647\u0627 \u062F\u0633\u062A\u0648\u0631\u0627\u062A \u0633\u0641\u0627\u0631\u0634\u06CC \u0647\u0633\u062A\u0646\u062F \u06A9\u0647 \u062F\u0631 \u067E\u06CC\u06A9\u0631\u0628\u0646\u062F\u06CC \u0634\u0645\u0627 \u06CC\u0627 \u062F\u0631 \u0641\u0627\u06CC\u0644\u200C\u0647\u0627\u06CC Markdown \u062F\u0633\u062A\u0648\u0631\u0627\u062A \u062A\u0639\u0631\u06CC\u0641 \u0634\u062F\u0647\u200C\u0627\u0646\u062F. \u0645\u06CC\u200C\u062A\u0648\u0627\u0646\u06CC\u062F \u0628\u0631\u0627\u06CC \u0647\u0631 Workflow \u06CC\u06A9 \u0645\u062F\u0644 \u0648 \u06CC\u06A9 \u06AF\u0648\u0646\u0647 \u0627\u0633\u062A\u062F\u0644\u0627\u0644 \u062A\u0639\u06CC\u06CC\u0646 \u06A9\u0646\u06CC\u062F.",
      "settings.agentBehaviour.workflows.empty": "\u0647\u06CC\u0686 \u062F\u0633\u062A\u0648\u0631 \u0633\u0641\u0627\u0631\u0634\u06CC \u06CC\u0627\u0641\u062A \u0646\u0634\u062F. \u062F\u0633\u062A\u0648\u0631\u0627\u062A \u0631\u0627 \u0628\u0647 kilo2.json \u06CC\u0627 \u06CC\u06A9 \u0641\u0627\u06CC\u0644 Markdown \u062F\u0631 .kilo2/command \u0627\u0636\u0627\u0641\u0647 \u06A9\u0646\u06CC\u062F.",
      "settings.agentBehaviour.workflows.detail.description": "\u062A\u0648\u0636\u06CC\u062D\u0627\u062A",
