      "settings.agentBehaviour.createMode.name.placeholder": "\u0645\u062B\u0644\u0627\u064B reviewer",
      "settings.agentBehaviour.createMode.name.description": "\u0634\u0646\u0627\u0633\u0647 \u06CC\u06A9\u062A\u0627 \u0628\u0631\u0627\u06CC \u062D\u0627\u0644\u062A. \u0641\u0642\u0637 \u0627\u0632 \u062D\u0631\u0648\u0641 \u06A9\u0648\u0686\u06A9\u060C \u0627\u0639\u062F\u0627\u062F \u0648 \u062E\u0637 \u062A\u06CC\u0631\u0647 \u0627\u0633\u062A\u0641\u0627\u062F\u0647 \u06A9\u0646\u06CC\u062F.",
      "settings.agentBehaviour.createMode.description": "\u062A\u0648\u0636\u06CC\u062D\u0627\u062A",
      "settings.agentBehaviour.createMode.description.placeholder": "\u0645\u062B\u0644\u0627\u064B \u06A9\u062F \u0631\u0627 \u0627\u0632 \u0646\u0638\u0631 \u06A9\u06CC\u0641\u06CC\u062A \u0648 \u0628\u0647\u062A\u0631\u06CC\u0646 \u0631\u0648\u0634\u200C\u0647\u0627 \u0628\u0631\u0631\u0633\u06CC \u0645\u06CC\u200C\u06A9\u0646\u062F",
      "settings.agentBehaviour.createMode.description.help": "\u062A\u0648\u0636\u06CC\u062D \u06A9\u0648\u062A\u0627\u0647\u06CC \u0627\u0632 \u0639\u0645\u0644\u06A9\u0631\u062F \u0627\u06CC\u0646 \u062D\u0627\u0644\u062A.",
      "settings.agentBehaviour.createMode.prompt": "\u067E\u0631\u0627\u0645\u067E\u062A \u0633\u06CC\u0633\u062A\u0645",
      "settings.agentBehaviour.createMode.prompt.placeholder": "\u0645\u062B\u0644\u0627\u064B \u0634\u0645\u0627 \u06CC\u06A9 \u0628\u0627\u0632\u0628\u06CC\u0646 \u06A9\u062F \u0647\u0633\u062A\u06CC\u062F. \u0628\u0631 \u06A9\u06CC\u0641\u06CC\u062A \u06A9\u062F\u060C \u0628\u0647\u062A\u0631\u06CC\u0646 \u0631\u0648\u0634\u200C\u0647\u0627 \u0648 \u0628\u0627\u06AF\u200C\u0647\u0627\u06CC \u0627\u062D\u062A\u0645\u0627\u0644\u06CC \u062A\u0645\u0631\u06A9\u0632 \u06A9\u0646\u06CC\u062F.",
      "settings.agentBehaviour.createMode.prompt.help": "\u062F\u0633\u062A\u0648\u0631\u0627\u0644\u0639\u0645\u0644\u200C\u0647\u0627\u06CC \u0639\u0627\u0645\u0644 \u0647\u0648\u0634 \u0645\u0635\u0646\u0648\u0639\u06CC \u0647\u0646\u06AF\u0627\u0645 \u0627\u0633\u062A\u0641\u0627\u062F\u0647 \u0627\u0632 \u0627\u06CC\u0646 \u062D\u0627\u0644\u062A.",
