      "settings.agentBehaviour.createMode.nameInvalid": "\u0646\u0627\u0645 \u0628\u0627\u06CC\u062F \u0628\u0627 \u06CC\u06A9 \u062D\u0631\u0641 \u06A9\u0648\u0686\u06A9 \u0634\u0631\u0648\u0639 \u0634\u0648\u062F \u0648 \u0641\u0642\u0637 \u0634\u0627\u0645\u0644 \u062D\u0631\u0648\u0641 \u06A9\u0648\u0686\u06A9\u060C \u0627\u0639\u062F\u0627\u062F \u0648 \u062E\u0637 \u062A\u06CC\u0631\u0647 \u0628\u0627\u0634\u062F",
      "settings.agentBehaviour.createMode.nameTaken": "\u06CC\u06A9 \u062D\u0627\u0644\u062A \u0628\u0627 \u0627\u06CC\u0646 \u0646\u0627\u0645 \u0627\u0632 \u0642\u0628\u0644 \u0648\u062C\u0648\u062F \u062F\u0627\u0631\u062F",
      "settings.agentBehaviour.importMode": "\u0648\u0627\u0631\u062F \u06A9\u0631\u062F\u0646",
      "settings.agentBehaviour.importMode.invalidName": "\u0646\u0627\u0645 \u062D\u0627\u0644\u062A \u062F\u0631 \u0641\u0627\u06CC\u0644 \u0646\u0627\u0645\u0639\u062A\u0628\u0631 \u0627\u0633\u062A. \u0646\u0627\u0645 \u0628\u0627\u06CC\u062F \u0628\u0627 \u06CC\u06A9 \u062D\u0631\u0641 \u06A9\u0648\u0686\u06A9 \u0634\u0631\u0648\u0639 \u0634\u0648\u062F \u0648 \u0641\u0642\u0637 \u0634\u0627\u0645\u0644 \u062D\u0631\u0648\u0641 \u06A9\u0648\u0686\u06A9\u060C \u0627\u0639\u062F\u0627\u062F \u0648 \u062E\u0637 \u062A\u06CC\u0631\u0647 \u0628\u0627\u0634\u062F.",
      "settings.agentBehaviour.importMode.nameTaken": "\u06CC\u06A9 \u062D\u0627\u0644\u062A \u0628\u0627 \u0627\u06CC\u0646 \u0646\u0627\u0645 \u0627\u0632 \u0642\u0628\u0644 \u0648\u062C\u0648\u062F \u062F\u0627\u0631\u062F.",
      "settings.agentBehaviour.importMode.invalidJson": "\u0641\u0627\u06CC\u0644 JSON \u0646\u0627\u0645\u0639\u062A\u0628\u0631 \u0627\u0633\u062A. \u0644\u0637\u0641\u0627\u064B \u06CC\u06A9 \u0641\u0627\u06CC\u0644 \u062A\u0639\u0631\u06CC\u0641 \u0639\u0627\u0645\u0644 \u0645\u0639\u062A\u0628\u0631 \u0627\u0646\u062A\u062E\u0627\u0628 \u06A9\u0646\u06CC\u062F.",
      "settings.agentBehaviour.importMode.tooLarge": "\u0641\u0627\u06CC\u0644 \u0628\u06CC\u0634 \u0627\u0632 \u062D\u062F \u0628\u0632\u0631\u06AF \u0627\u0633\u062A. \u062A\u0639\u0631\u06CC\u0641 \u0639\u0627\u0645\u0644\u200C\u0647\u0627 \u0628\u0627\u06CC\u062F \u06A9\u0645\u062A\u0631 \u0627\u0632 \u06F1 \u0645\u06AF\u0627\u0628\u0627\u06CC\u062A \u0628\u0627\u0634\u0646\u062F.",
