      "settings.display.fontSize.description": "\u0627\u0646\u062F\u0627\u0632\u0647 \u0642\u0644\u0645 \u0631\u0627\u0628\u0637 \u06A9\u0627\u0631\u0628\u0631\u06CC \u0648\u0628\u200C\u0648\u06CC\u0648 Kilo \u0631\u0627 \u0645\u0633\u062A\u0642\u0644 \u0627\u0632 VS Code \u062A\u0646\u0638\u06CC\u0645 \u06A9\u0646\u06CC\u062F.",
      "settings.display.reasoningDisplay.title": "\u0628\u0644\u0648\u06A9\u200C\u0647\u0627\u06CC \u0627\u0633\u062A\u062F\u0644\u0627\u0644",
      "settings.display.reasoningDisplay.description": "\u0627\u0646\u062A\u062E\u0627\u0628 \u06A9\u0646\u06CC\u062F \u06A9\u0647 \u0628\u0644\u0648\u06A9\u200C\u0647\u0627\u06CC \u0627\u0633\u062A\u062F\u0644\u0627\u0644 \u0686\u06AF\u0648\u0646\u0647 \u0634\u0631\u0648\u0639 \u0634\u0648\u0646\u062F. \u0628\u0627\u0632 \u0645\u062A\u0646 \u06A9\u0627\u0645\u0644 \u0631\u0627 \u0646\u0634\u0627\u0646 \u0645\u06CC\u200C\u062F\u0647\u062F\u060C \u067E\u06CC\u0634\u200C\u0646\u0645\u0627\u06CC\u0634 \u0622\u0646 \u0631\u0627 \u0628\u0647 \u06CC\u06A9 \u067E\u06CC\u0634\u200C\u0646\u0645\u0627\u06CC\u0634 \u06A9\u0648\u062A\u0627\u0647 \u0642\u0627\u0628\u0644 \u0627\u0633\u06A9\u0631\u0648\u0644 \u0645\u062D\u062F\u0648\u062F \u0645\u06CC\u200C\u06A9\u0646\u062F\u060C \u0648 \u0639\u0646\u0648\u0627\u0646 \u062A\u0646\u0647\u0627 \u0639\u0646\u0648\u0627\u0646 \u0648 \u0646\u0634\u0627\u0646\u06AF\u0631 \u067E\u062E\u0634 \u062C\u0631\u06CC\u0627\u0646\u06CC \u0631\u0627 \u062A\u0627 \u0632\u0645\u0627\u0646\u06CC \u06A9\u0647 \u0622\u0646 \u0631\u0627 \u0628\u0627\u0632 \u06A9\u0646\u06CC\u062F \u0646\u0645\u0627\u06CC\u0634 \u0645\u06CC\u200C\u062F\u0647\u062F.",
