      "settings.display.shiftTabCycle.title": "\u0686\u0631\u062E\u0634 \u0633\u0637\u062D \u0627\u0633\u062A\u062F\u0644\u0627\u0644 \u0628\u0627 Shift+Tab",
      "settings.display.shiftTabCycle.description": "\u062F\u0631 \u0648\u0631\u0648\u062F\u06CC \u067E\u0631\u0627\u0645\u067E\u062A\u060C Shift+Tab \u0631\u0627 \u0641\u0634\u0627\u0631 \u062F\u0647\u06CC\u062F \u062A\u0627 \u0628\u0647 \u0633\u0637\u062D \u062A\u0644\u0627\u0634 \u0627\u0633\u062A\u062F\u0644\u0627\u0644 \u0628\u0639\u062F\u06CC \u0628\u0631\u0648\u06CC\u062F. \u0628\u0631\u0627\u06CC \u062D\u0641\u0638 \u0639\u0645\u0644\u06A9\u0631\u062F Shift+Tab \u062C\u0647\u062A \u0646\u0627\u0648\u0628\u0631\u06CC \u0641\u0648\u06A9\u0648\u0633 \u0635\u0641\u062D\u0647\u200C\u06A9\u0644\u06CC\u062F\u060C \u0627\u06CC\u0646 \u06AF\u0632\u06CC\u0646\u0647 \u0631\u0627 \u063A\u06CC\u0631\u0641\u0639\u0627\u0644 \u06A9\u0646\u06CC\u062F.",
