      "settings.display.shortcutHints.description": "\u0645\u06CC\u0627\u0646\u0628\u0631 \u0635\u0641\u062D\u0647\u200C\u06A9\u0644\u06CC\u062F\u06CC \u0645\u062A\u0646\u0627\u0633\u0628 \u0628\u0627 \u06A9\u0627\u0631\u06CC \u06A9\u0647 \u0627\u06A9\u0646\u0648\u0646 \u0627\u0646\u062C\u0627\u0645 \u0645\u06CC\u200C\u062F\u0647\u06CC\u062F \u0631\u0627 \u062F\u0631 \u0627\u0639\u0644\u0627\u0646 \u062E\u0627\u0644\u06CC \u0646\u0645\u0627\u06CC\u0634 \u0645\u06CC\u200C\u062F\u0647\u062F\u060C \u0645\u062B\u0644\u0627\u064B \u0646\u062D\u0648\u0647 \u0627\u0641\u0632\u0648\u062F\u0646 \u06A9\u062F \u0627\u0646\u062A\u062E\u0627\u0628\u200C\u0634\u062F\u0647 \u06CC\u0627 \u0628\u0627\u0632\u06AF\u0634\u062A \u0628\u0647 \u0627\u0639\u0644\u0627\u0646.",
