      "settings.display.tokenThroughput.description": "Display the text-generation rate (tokens/sec) on the latest assistant message footer. Shown by default; disable this setting to hide it when needed.",
      "settings.display.autoApprovalReason.title": "\u0646\u0645\u0627\u06CC\u0634 \u062F\u0644\u06CC\u0644 \u062A\u0623\u06CC\u06CC\u062F \u062E\u0648\u062F\u06A9\u0627\u0631",
      "settings.display.autoApprovalReason.description": "\u0646\u0634\u0627\u0646 \u0645\u06CC\u200C\u062F\u0647\u062F \u0686\u0631\u0627 \u06CC\u06A9 \u0641\u0631\u0627\u062E\u0648\u0627\u0646\u06CC \u0627\u0628\u0632\u0627\u0631 \u0628\u0647\u200C\u0637\u0648\u0631 \u062E\u0648\u062F\u06A9\u0627\u0631 \u062A\u0623\u06CC\u06CC\u062F \u0634\u062F\u0647 \u0627\u0633\u062A\u060C \u0645\u0627\u0646\u0646\u062F \u06CC\u06A9 \u0642\u0627\u0646\u0648\u0646 \u0645\u062C\u0648\u0632 \u0645\u0637\u0627\u0628\u0642 \u06CC\u0627 \u067E\u06CC\u0634\u200C\u0641\u0631\u0636 \u0639\u0627\u0645\u0644.",
      "chat.throughput.tooltip": "\u0645\u06CC\u0627\u0646\u06AF\u06CC\u0646 {{speed}} \u062A\u0648\u06A9\u0646/\u062B\u0627\u0646\u06CC\u0647 \u0628\u0631\u0627\u06CC \u0627\u06CC\u0646 \u0646\u0648\u0628\u062A. \u0634\u0627\u0645\u0644 \u062A\u0648\u06A9\u0646\u200C\u0647\u0627\u06CC \u062E\u0631\u0648\u062C\u06CC \u0648 \u0627\u0633\u062A\u062F\u0644\u0627\u0644 \u0645\u06CC\u200C\u0634\u0648\u062F\u061B \u0632\u0645\u0627\u0646 \u0627\u062C\u0631\u0627\u06CC \u0627\u0628\u0632\u0627\u0631 \u0648 \u0627\u0646\u062A\u0638\u0627\u0631 \u0631\u0627 \u0634\u0627\u0645\u0644 \u0646\u0645\u06CC\u200C\u0634\u0648\u062F.",
      "chat.throughput.tooltip.missing": "\u0645\u0639\u06CC\u0627\u0631\u0647\u0627\u06CC \u062A\u0648\u0627\u0646 \u0639\u0645\u0644\u06CC\u0627\u062A\u06CC \u0628\u0631\u0627\u06CC \u0627\u06CC\u0646 \u0646\u0648\u0628\u062A \u062F\u0631 \u062F\u0633\u062A\u0631\u0633 \u0646\u06CC\u0633\u062A.",
