      "settings.providers.smallModel.title": "\u0645\u062F\u0644 \u0633\u0628\u06A9",
      "settings.providers.smallModel.description": "\u0645\u062F\u0644 \u0633\u0628\u06A9\u200C\u0648\u0632\u0646 \u0628\u0631\u0627\u06CC \u062A\u0648\u0644\u06CC\u062F \u0639\u0646\u0648\u0627\u0646\u060C \u062A\u0648\u0644\u06CC\u062F \u067E\u06CC\u0627\u0645 \u06A9\u0627\u0645\u06CC\u062A\u060C \u0628\u0647\u0628\u0648\u062F \u067E\u0631\u0627\u0645\u067E\u062A \u0648 \u0633\u0627\u06CC\u0631 \u0648\u0638\u0627\u06CC\u0641 \u0633\u0631\u06CC\u0639",
      "settings.providers.subagentModel.title": "\u0645\u062F\u0644 \u0632\u06CC\u0631\u0639\u0627\u0645\u0644",
      "settings.providers.subagentModel.description": "\u0645\u062F\u0644 \u067E\u06CC\u0634\u200C\u0641\u0631\u0636 \u0648 \u0645\u06CC\u0632\u0627\u0646 \u0627\u0633\u062A\u062F\u0644\u0627\u0644 \u0628\u0631\u0627\u06CC \u0632\u06CC\u0631\u0639\u0627\u0645\u0644\u200C\u0647\u0627\u06CC \u0627\u0628\u0632\u0627\u0631-\u0648\u0638\u06CC\u0641\u0647. \u0628\u0631\u0627\u06CC \u0628\u0647 \u0627\u0631\u062B \u0628\u0631\u062F\u0646 \u0645\u062F\u0644 \u0639\u0627\u0645\u0644 \u0641\u0631\u0627\u062E\u0648\u0627\u0646\u0646\u062F\u0647\u060C \u062E\u0627\u0644\u06CC \u0628\u06AF\u0630\u0627\u0631\u06CC\u062F.",
      "settings.models.hidePromptTraining.title": "\u067E\u0646\u0647\u0627\u0646 \u06A9\u0631\u062F\u0646 \u0645\u062F\u0644\u200C\u0647\u0627\u06CC \u0622\u0645\u0648\u0632\u0634 \u067E\u0631\u0627\u0645\u067E\u062A",
