      "agentManager.settings.branchPrefix.description": "\u067E\u06CC\u0634\u0648\u0646\u062F \u0634\u0627\u062E\u0647\u200C\u0647\u0627\u06CC\u06CC \u06A9\u0647 \u062F\u0631 \u0647\u0645\u0647 \u067E\u0631\u0648\u0698\u0647\u200C\u0647\u0627 \u062E\u0648\u062F\u06A9\u0627\u0631 \u0646\u0627\u0645\u200C\u06AF\u0630\u0627\u0631\u06CC \u0645\u06CC\u200C\u0634\u0648\u0646\u062F\u060C \u0628\u0631\u0627\u06CC \u0645\u062B\u0627\u0644 feature/. \u0628\u0631\u0627\u06CC \u0646\u0627\u0645\u200C\u0647\u0627\u06CC \u0635\u0631\u06CC\u062D \u0634\u0627\u062E\u0647\u200C\u0647\u0627 \u0627\u0639\u0645\u0627\u0644 \u0646\u0645\u06CC\u200C\u0634\u0648\u062F. \u0628\u0631\u0627\u06CC \u0646\u062F\u0627\u0634\u062A\u0646 \u067E\u06CC\u0634\u0648\u0646\u062F\u060C \u062E\u0627\u0644\u06CC \u0628\u06AF\u0630\u0627\u0631\u06CC\u062F.",
      "agentManager.settings.worktreePool.title": "\u0622\u0645\u0627\u062F\u0647\u200C\u0633\u0627\u0632\u06CC \u0627\u0632 \u067E\u06CC\u0634 worktree\u0647\u0627",
      "agentManager.settings.worktreePool.description": "\u06CC\u06A9 worktree \u0622\u0645\u0627\u062F\u0647 \u0631\u0627 \u062F\u0631 \u067E\u0633\u200C\u0632\u0645\u06CC\u0646\u0647 \u0641\u0631\u0627\u0647\u0645 \u06A9\u0646\u06CC\u062F \u062A\u0627 \u0646\u0634\u0633\u062A\u200C\u0647\u0627\u06CC \u062C\u062F\u06CC\u062F Agent Manager \u0633\u0631\u06CC\u0639\u200C\u062A\u0631 \u0634\u0631\u0648\u0639 \u0634\u0648\u0646\u062F. \u0628\u0631\u0627\u06CC \u0647\u0631 \u067E\u0631\u0648\u0698\u0647 \u0628\u0627\u0632\u060C \u06CC\u06A9 checkout \u0631\u0648\u06CC \u062F\u06CC\u0633\u06A9 \u0641\u0636\u0627\u06CC \u0627\u0636\u0627\u0641\u06CC \u0645\u0635\u0631\u0641 \u0645\u06CC\u200C\u06A9\u0646\u062F.",
