      "prompt.action.sandbox.description.enabled": "\uC4F0\uAE30\uB294 \uD504\uB85C\uC81D\uD2B8 \uBC0F Kilo \uB514\uB809\uD130\uB9AC\uB85C \uC81C\uD55C\uB429\uB2C8\uB2E4.",
      "prompt.action.sandbox.description.escalation": "\uAD8C\uD55C \uADDC\uCE59\uACFC \uC790\uB3D9 \uC2B9\uC778\uC740 \uC0CC\uB4DC\uBC15\uC2A4 \uC548\uC5D0\uC11C \uC801\uC6A9\uB429\uB2C8\uB2E4. \uC0CC\uB4DC\uBC15\uC2A4\uB97C \uBC97\uC5B4\uB098\uC57C \uD558\uB294 \uBA85\uB839\uC740 \uD56D\uC0C1 \uD655\uC778\uD569\uB2C8\uB2E4.",
