      "settings.autoCleanup.progress.deleting": "\uC138\uC158 \uC0AD\uC81C \uC911: {{processed}}/{{total}}\uAC1C \uCC98\uB9AC\uB428({{deleted}}\uAC1C \uC0AD\uC81C, {{failed}}\uAC1C \uC2E4\uD328)",
      "settings.autoCleanup.runNow": "\uC9C0\uAE08 \uC815\uB9AC \uC2E4\uD589",
      "settings.autoCleanup.runNow.confirm": "\uC774 \uCEF4\uD4E8\uD130\uC758 \uBAA8\uB4E0 \uD504\uB85C\uC81D\uD2B8\uC640 \uBAA8\uB4E0 Kilo \uD074\uB77C\uC774\uC5B8\uD2B8\uC5D0 \uAC78\uCCD0 \uB9CC\uB8CC\uB41C \uC138\uC158\uC744 \uC601\uAD6C\uC801\uC73C\uB85C \uC0AD\uC81C\uD560\uAE4C\uC694?",
