      "settings.context.autoCompaction.title": "\uC790\uB3D9 \uC555\uCD95",
      "settings.context.autoCompaction.description": "\uCEE8\uD14D\uC2A4\uD2B8\uAC00 \uD55C\uB3C4\uC5D0 \uB3C4\uB2EC\uD558\uAE30 \uC804\uC5D0 \uC790\uB3D9\uC73C\uB85C \uC555\uCD95",
      "settings.context.compaction.title": "\uC555\uCD95",
      "settings.context.compactionModel.title": "\uC555\uCD95 \uBAA8\uB378",
      "settings.context.compactionModel.description": "\uC790\uB3D9 \uBC0F \uC218\uB3D9 \uC555\uCD95\uC5D0 \uC0AC\uC6A9\uD558\uB294 \uBAA8\uB378\uC785\uB2C8\uB2E4. \uCC44\uD305 \uBAA8\uB378\uC744 \uC0AC\uC6A9\uD558\uB824\uBA74 \uC124\uC815\uD558\uC9C0 \uC54A\uC740 \uC0C1\uD0DC\uB85C \uB450\uC138\uC694. \uBE44\uC6A9, \uC18D\uB3C4 \uBC0F \uC694\uC57D \uD488\uC9C8\uC740 \uBAA8\uB378\uC5D0 \uB530\uB77C \uB2EC\uB77C\uC9D1\uB2C8\uB2E4.",
      "settings.context.compactionModel.useChatModel": "\uCC44\uD305 \uBAA8\uB378 \uC0AC\uC6A9",
      "settings.context.compactionModel.hint": "\uC555\uCD95\uC5D0 \uC0AC\uC6A9\uB418\uB294 \uBAA8\uB378\uC744 \uC120\uD0DD\uD558\uB824\uBA74 \uBAA8\uB378 \uC124\uC815\uC744 \uCC38\uC870\uD558\uC138\uC694.",
      "settings.context.compactionLimit.title": "\uC790\uB3D9 \uC555\uCD95 \uD55C\uB3C4",
      "settings.context.compactionLimit.description": "\uCEE8\uD14D\uC2A4\uD2B8\uAC00 \uBAA8\uB378 \uCC3D\uC758 \uC774 \uBE44\uC728\uC5D0 \uB3C4\uB2EC\uD558\uBA74 \uC555\uCD95\uD569\uB2C8\uB2E4. \uC548\uC804 \uBC84\uD37C\uB9CC \uC0AC\uC6A9\uD558\uB824\uBA74 \uBE44\uC6CC \uB450\uC138\uC694.",
      "settings.context.compactionKeep.title": "\uCD5C\uADFC \uD1A0\uD070 \uC720\uC9C0",
      "settings.context.compactionKeep.description": "\uCEE8\uD14D\uC2A4\uD2B8\uB97C \uC555\uCD95\uD560 \uB54C \uADF8\uB300\uB85C \uC720\uC9C0\uD560 \uCD5C\uADFC \uD1A0\uD070 \uC218\uC785\uB2C8\uB2E4. \uBE44\uC6CC \uB450\uBA74 15,000\uC744 \uC720\uC9C0\uD569\uB2C8\uB2E4.",
      "settings.context.compactionBuffer.title": "\uC555\uCD95 \uBC84\uD37C",
      "settings.context.compactionBuffer.description": "\uC555\uCD95 \uC804\uC5D0 \uBAA8\uB378 \uCEE8\uD14D\uC2A4\uD2B8 \uD55C\uB3C4 \uC544\uB798\uB85C \uBE44\uC6CC \uB458 \uD1A0\uD070 \uC218\uC785\uB2C8\uB2E4. \uBE44\uC6CC \uB450\uBA74 15%(\uCD5C\uC18C 16,000)\uB97C \uBE44\uC6CC \uB461\uB2C8\uB2E4.",
