      "settings.commitMessage.title": "Commit Message",
      "settings.commitMessage.override.title": "\uC0AC\uC6A9\uC790 \uC9C0\uC815 prompt \uC0AC\uC6A9",
      "settings.commitMessage.override.description": "\uAE30\uBCF8 commit message\uC758 prompt\uB97C \uC7AC\uC815\uC758\uD569\uB2C8\uB2E4. \uD65C\uC131\uD654\uB418\uBA74 \uC0AC\uC6A9\uC790 \uC9C0\uC815 prompt\uAC00 \uAE30\uBCF8 \uC81C\uACF5\uB418\uB294 conventional commits\uC758 prompt\uB97C \uC644\uC804\uD788 \uB300\uCCB4\uD569\uB2C8\uB2E4.",
      "settings.commitMessage.prompt.title": "\uC0AC\uC6A9\uC790 \uC9C0\uC815 prompt",
      "settings.commitMessage.prompt.description": "commit messages\uB97C \uC0DD\uC131\uD560 \uB54C AI\uB85C \uC804\uC1A1\uB418\uB294 \uC2DC\uC2A4\uD15C prompt\uC785\uB2C8\uB2E4. \uC774\uB294 \uAE30\uBCF8 prompt\uB97C \uC644\uC804\uD788 \uB300\uCCB4\uD569\uB2C8\uB2E4.",
      "settings.commitMessage.prompt.placeholder": "\uC608: \uC2A4\uD398\uC778\uC5B4\uB85C conventional commits \uD615\uC2DD\uC744 \uB530\uB77C commit messages\uB97C \uC0DD\uC131\uD574\uC918. \uC624\uC9C1 commit message\uB9CC \uBC18\uD658\uD560 \uAC83.",
      "settings.commitMessage.language.sync": "UI \uC5B8\uC5B4\uC640 \uB3D9\uAE30\uD654",
      "settings.commitMessage.language.description": "AI \uC0DD\uC131\uB41C \uCEE4\uBC0B \uBA54\uC2DC\uC9C0\uC5D0 \uC0AC\uC6A9\uD560 \uC5B8\uC5B4\uB97C \uC120\uD0DD\uD558\uC2ED\uC2DC\uC624.:",
      "settings.display.preview.title": "\uBBF8\uB9AC\uBCF4\uAE30",
      "settings.display.presets.title": "\uD45C\uC2DC \uD504\uB9AC\uC14B",
      "settings.display.presets.description": "\uC544\uB798 \uD45C\uC2DC \uC635\uC158\uC744 \uBCC0\uACBD\uD558\uBA70 \uAD8C\uD55C\uC740 \uBCC0\uACBD\uD558\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4. \uC801\uC6A9\uD558\uB824\uBA74 \uC800\uC7A5\uD558\uC138\uC694.",
      "settings.display.preview.model": "\uC0D8\uD50C \uBAA8\uB378",
      "settings.display.preview.prompt": "\uC778\uC0AC\uB9D0\uC5D0\uC11C \uC5EC\uBD84\uC758 \uACF5\uBC31\uC744 \uC81C\uAC70\uD558\uACE0 \uD14C\uC2A4\uD2B8\uB97C \uD655\uC778\uD558\uC138\uC694.",
      "settings.display.preview.reasoning": "**\uC778\uC0AC\uB9D0\uC744 \uD655\uC778\uD569\uB2C8\uB2E4.** \uC774 \uD568\uC218\uB294 \uC77C\uBC18 \uC774\uB984\uACFC \uC591\uCABD \uB05D\uC5D0 \uC5EC\uBD84\uC758 \uACF5\uBC31\uC774 \uC788\uB294 \uC774\uB984\uC5D0 \uB300\uD574 \uAC19\uC740 \uC778\uC0AC\uB9D0\uC744 \uC0DD\uC131\uD574\uC57C \uD569\uB2C8\uB2E4. \uAE30\uC874 \uD568\uC218 \uC2DC\uADF8\uB2C8\uCC98\uC640 \uC778\uC0AC\uB9D0 \uD615\uC2DD\uC740 \uC720\uC9C0\uD558\uACE0, \uC774\uB984\uC774 \uBC18\uD658 \uBB38\uC790\uC5F4\uC5D0 \uB4E4\uC5B4\uAC00\uB294 \uBC29\uC2DD\uB9CC \uBCC0\uACBD\uD569\uB2C8\uB2E4.\n\n`  Ada  ` \uAC19\uC740 \uC785\uB825\uC5D0\uC11C \uC6D0\uCE58 \uC54A\uB294 \uACF5\uBC31\uC740 \uC785\uB825\uC5D0 \uC18D\uD558\uBA70 \uC778\uC0AC\uB9D0 \uD15C\uD50C\uB9BF\uC5D0 \uC18D\uD558\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4. \uC644\uC131\uB41C \uC778\uC0AC\uB9D0\uC744 \uD2B8\uB9BC\uD558\uBA74 \uC774\uB984 \uC606\uC5D0 \uACF5\uBC31\uC774 \uB0A8\uC2B5\uB2C8\uB2E4. \uB530\uB77C\uC11C \uD2B8\uB9BC \uC791\uC5C5\uC740 \uC774\uB984\uC744 \uC0BD\uC785\uD558\uAE30 \uC804\uC5D0 \uC218\uD589\uD574\uC57C \uD569\uB2C8\uB2E4.\n\n\uBB38\uC790\uC5F4 \uBB38\uC11C\uB97C \uD655\uC778\uD558\uC5EC `trim()`\uC774 \uC591\uCABD \uB05D\uC758 \uACF5\uBC31\uC744 \uC81C\uAC70\uD558\uACE0 \uC0C8 \uBB38\uC790\uC5F4\uC744 \uBC18\uD658\uD558\uB294\uC9C0 \uD655\uC778\uD569\uB2C8\uB2E4. \uC6D0\uBCF8 \uC785\uB825\uC740 \uBCC0\uACBD\uD558\uC9C0 \uC54A\uC544\uC57C \uD569\uB2C8\uB2E4. \uC774 \uBCC0\uACBD\uC5D0\uB294 \uC815\uADDC\uC2DD, \uCD94\uAC00 \uC758\uC874\uC131 \uB610\uB294 \uBCC4\uB3C4\uC758 \uB3C4\uC6B0\uBBF8 \uD568\uC218\uAC00 \uD544\uC694\uD558\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.\n\n\uC774\uB984 \uC548\uC758 \uACF5\uBC31\uC740 \uADF8\uB300\uB85C \uC720\uC9C0\uB418\uC5B4\uC57C \uD569\uB2C8\uB2E4. `Ada Lovelace` \uAC19\uC740 \uC774\uB984\uC774 `AdaLovelace`\uAC00 \uB418\uC5B4\uC11C\uB294 \uC548 \uB418\uBA70 \uB300\uC18C\uBB38\uC790\uB3C4 \uBC14\uB00C\uC9C0 \uC54A\uC544\uC57C \uD569\uB2C8\uB2E4. \uBE48 \uC785\uB825\uC774\uB098 \uACF5\uBC31\uB9CC \uC788\uB294 \uC785\uB825\uC5D0\uB294 \uC774 \uC9D1\uC911\uC801\uC778 \uC218\uC815\uC758 \uC77C\uBD80\uB85C \uC0C8\uB85C\uC6B4 \uB300\uCCB4 \uC778\uC0AC\uB9D0\uC774 \uD544\uC694\uD558\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.\n\n\uD15C\uD50C\uB9BF\uC774 \uD604\uC7AC `name`\uC744 \uC0AC\uC6A9\uD558\uB294 \uACF3\uC5D0\uC11C `name.trim()`\uC744 \uC0AC\uC6A9\uD558\uBA74 \uBCC0\uACBD\uC744 return \uC2DD \uC548\uC5D0 \uB458 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uC8FC\uBCC0 \uBB38\uC7A5 \uBD80\uD638\uC640 \uC778\uC0AC\uB9D0 \uB4A4\uC758 \uC758\uB3C4\uC801\uC778 \uACF5\uBC31\uC740 \uC720\uC9C0\uD569\uB2C8\uB2E4. \uC774\uB807\uAC8C \uD558\uBA74 diff\uAC00 \uC791\uAC8C \uC720\uC9C0\uB418\uACE0 \uB3D9\uC791\uC744 \uAC80\uD1A0\uD558\uAE30 \uC27D\uC2B5\uB2C8\uB2E4.\n\n\uB9C8\uC9C0\uB9C9\uC73C\uB85C `bun test greeting.test.ts`\uB97C \uC2E4\uD589\uD558\uACE0 \uB450 \uACB0\uACFC\uB97C \uD655\uC778\uD569\uB2C8\uB2E4. \uACF5\uBC31\uC774 \uC788\uB294 \uC774\uB984 \uC0AC\uB840\uB294 \uC5EC\uBD84\uC758 \uACF5\uBC31\uC774 \uC81C\uAC70\uB428\uC744 \uD655\uC778\uD558\uACE0, \uC77C\uBC18 \uC774\uB984 \uC0AC\uB840\uB294 \uAE30\uC874 \uCD9C\uB825\uC744 \uBCF4\uD638\uD569\uB2C8\uB2E4. \uBCC0\uACBD \uC0AC\uD56D\uACFC \uD14C\uC2A4\uD2B8 \uACB0\uACFC\uB294 \uBA85\uB839\uC774 \uC644\uB8CC\uB41C \uD6C4\uC5D0\uB9CC \uBCF4\uACE0\uD569\uB2C8\uB2E4.",
      "settings.display.preview.shell": "\uC778\uC0AC\uB9D0 \uD14C\uC2A4\uD2B8 \uD655\uC778",
      "settings.display.preview.shellOutput": "bun test greeting.test.ts\n\n[pass] \uC5EC\uBD84\uC758 \uACF5\uBC31 \uC81C\uAC70\n[pass] \uC77C\uBC18 \uC774\uB984 \uC720\uC9C0\n\n2\uAC1C \uD14C\uC2A4\uD2B8 \uD1B5\uACFC",
      "settings.display.preview.query": "\uBB38\uC790\uC5F4 \uD2B8\uB9BC",
      "settings.display.preview.result": "trim()\uC740 \uBB38\uC790\uC5F4 \uC591\uCABD \uB05D\uC758 \uACF5\uBC31\uC744 \uC81C\uAC70\uD569\uB2C8\uB2E4.",
      "settings.display.preview.answer": "\uC778\uC0AC\uB9D0\uC744 \uC5C5\uB370\uC774\uD2B8\uD558\uC5EC \uC5EC\uBD84\uC758 \uACF5\uBC31\uC744 \uC81C\uAC70\uD588\uC2B5\uB2C8\uB2E4. \uB450 \uD14C\uC2A4\uD2B8 \uBAA8\uB450 \uD1B5\uACFC\uD569\uB2C8\uB2E4.",
      "settings.display.username.title": "\uC0AC\uC6A9\uC790 \uC774\uB984",
      "settings.display.username.description": "\uB300\uD654\uC5D0 \uD45C\uC2DC\uB418\uB294 \uC0AC\uC6A9\uC790 \uC815\uC758 \uC0AC\uC6A9\uC790 \uC774\uB984",
      "settings.display.fontSize.title": "\uAE00\uAF34 \uD06C\uAE30",
      "settings.display.fontSize.description": "VS Code\uC640 \uB3C5\uB9BD\uC801\uC73C\uB85C Kilo webview UI \uAE00\uAF34 \uD06C\uAE30\uB97C \uC870\uC815\uD569\uB2C8\uB2E4.",
      "settings.display.reasoningDisplay.title": "\uCD94\uB860 \uBE14\uB85D",
      "settings.display.reasoningDisplay.description": "\uCD94\uB860 \uBE14\uB85D\uC758 \uC2DC\uC791 \uD45C\uC2DC \uBC29\uC2DD\uC744 \uC120\uD0DD\uD569\uB2C8\uB2E4. \uD3BC\uCE68\uC740 \uC804\uCCB4 \uD14D\uC2A4\uD2B8\uB97C \uD45C\uC2DC\uD558\uACE0, \uBBF8\uB9AC\uBCF4\uAE30\uB294 \uC9E7\uC740 \uC2A4\uD06C\uB864 \uBBF8\uB9AC\uBCF4\uAE30\uB85C \uC81C\uD55C\uD558\uBA70, \uD5E4\uB4DC\uB77C\uC778\uC740 \uC5F4\uAE30 \uC804\uAE4C\uC9C0 \uC81C\uBAA9\uACFC \uC2A4\uD2B8\uB9AC\uBC0D \uD45C\uC2DC\uAE30\uB9CC \uD45C\uC2DC\uD569\uB2C8\uB2E4.",
      "settings.display.reasoningDisplay.expanded": "\uD3BC\uCE68",
      "settings.display.reasoningDisplay.preview": "\uBBF8\uB9AC\uBCF4\uAE30",
      "settings.display.reasoningDisplay.headline": "\uD5E4\uB4DC\uB77C\uC778",
      "settings.display.shiftTabCycle.title": "Shift+Tab\uC73C\uB85C \uCD94\uB860 \uAC15\uB3C4 \uC804\uD658",
      "settings.display.shiftTabCycle.description": "\uD504\uB86C\uD504\uD2B8 \uC785\uB825\uB780\uC5D0\uC11C Shift+Tab\uC744 \uB20C\uB7EC \uB2E4\uC74C \uCD94\uB860 \uAC15\uB3C4 \uC218\uC900\uC73C\uB85C \uC804\uD658\uD569\uB2C8\uB2E4. Shift+Tab\uC744 \uD0A4\uBCF4\uB4DC \uD3EC\uCEE4\uC2A4 \uD0D0\uC0C9\uC5D0 \uC0AC\uC6A9\uD558\uB824\uBA74 \uBE44\uD65C\uC131\uD654\uD558\uC138\uC694.",
