      "agentManager.settings.branchPrefix.description": "\uBAA8\uB4E0 \uD504\uB85C\uC81D\uD2B8\uC5D0\uC11C \uC790\uB3D9\uC73C\uB85C \uC774\uB984\uC774 \uC9C0\uC815\uB418\uB294 \uBE0C\uB79C\uCE58\uC758 \uC811\uB450\uC0AC\uC785\uB2C8\uB2E4(\uC608: feature/). \uBA85\uC2DC\uC801\uC778 \uBE0C\uB79C\uCE58 \uC774\uB984\uC5D0\uB294 \uC801\uC6A9\uB418\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4. \uC811\uB450\uC0AC\uB97C \uC0AC\uC6A9\uD558\uC9C0 \uC54A\uC73C\uB824\uBA74 \uBE44\uC6CC \uB450\uC138\uC694.",
      "agentManager.settings.worktreePool.title": "Worktree \uBBF8\uB9AC \uC900\uBE44",
      "agentManager.settings.worktreePool.description": "\uBC31\uADF8\uB77C\uC6B4\uB4DC\uC5D0\uC11C \uC900\uBE44\uB41C worktree\uB97C \uBBF8\uB9AC \uB9CC\uB4E4\uC5B4 \uB450\uBA74 \uC0C8 Agent Manager \uC138\uC158\uC774 \uB354 \uBE60\uB974\uAC8C \uC2DC\uC791\uB429\uB2C8\uB2E4. \uC5F4\uB9B0 \uD504\uB85C\uC81D\uD2B8\uB9C8\uB2E4 checkout \uD558\uB098\uB97C \uC704\uD574 \uCD94\uAC00 \uB514\uC2A4\uD06C \uACF5\uAC04\uC744 \uC0AC\uC6A9\uD569\uB2C8\uB2E4.",
