      "agentManager.intro.title": "\uBCD1\uB82C \uC791\uC5C5. \uBCC4\uB3C4\uC758 worktree.",
      "agentManager.intro.subtitle": "worktree\uB294 \uC791\uC5C5\uC744 \uC704\uD55C \uBCC4\uB3C4 \uD3F4\uB354\uC640 \uBE0C\uB79C\uCE58\uC785\uB2C8\uB2E4. \uC5D0\uC774\uC804\uD2B8\uAC00 \uAC19\uC740 \uD30C\uC77C\uC744 \uD3B8\uC9D1\uD558\uC9C0 \uC54A\uACE0 \uB098\uB780\uD788 \uC791\uC5C5\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.",
      "agentManager.intro.graph.agent": "Kilo \uC5D0\uC774\uC804\uD2B8",
      "agentManager.intro.graph.pr": "Pull request",
      "agentManager.intro.updateTitle": "Kilo\uB85C \uCDA9\uB3CC \uD574\uACB0",
      "agentManager.intro.updateText": "Local\uC5D0 \uBCC0\uACBD \uC0AC\uD56D\uC744 \uC801\uC6A9\uD558\uAC70\uB098 pull request\uB97C \uBCD1\uD569\uD558\uAE30 \uC804\uC5D0 \uD574\uB2F9 worktree\uC758 \uC138\uC158\uC5D0\uC11C /update-from-base \uBA85\uB839\uC744 \uC2E4\uD589\uD558\uC138\uC694. Kilo\uAC00 \uBCA0\uC774\uC2A4 \uBE0C\uB79C\uCE58\uC758 \uCD5C\uC2E0 \uBCC0\uACBD \uC0AC\uD56D\uC744 \uBCD1\uD569\uD558\uACE0 \uBA3C\uC800 \uD574\uB2F9 worktree \uC548\uC5D0\uC11C \uCDA9\uB3CC\uC744 \uD574\uACB0\uD569\uB2C8\uB2E4.",
      "agentManager.intro.stage1.title": "\uB0B4 \uC800\uC7A5\uC18C",
      "agentManager.intro.stage1.text": "\uB85C\uCEEC \uD30C\uC77C\uC740 \uBCC0\uACBD\uB418\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4",
      "agentManager.intro.stage2.title": "\uC608: \uB450 \uC791\uC5C5\uC744 \uBCD1\uB82C\uB85C",
      "agentManager.intro.stage2.text": "\uB450 worktree\uB294 \uC774 \uC800\uC7A5\uC18C\uC5D0 \uC18D\uD569\uB2C8\uB2E4. \uB2E4\uB978 \uC800\uC7A5\uC18C\uC5D0\uB294 \uB2E4\uB978 \uD504\uB85C\uC81D\uD2B8\uB97C \uC120\uD0DD\uD558\uC138\uC694.",
      "agentManager.intro.stage3.title": "Worktree",
      "agentManager.intro.stage3.text": "\uC804\uC6A9 \uD3F4\uB354 + \uBE0C\uB79C\uCE58",
      "agentManager.intro.stage4.title": "\uC900\uBE44\uB418\uBA74 \uBCC0\uACBD \uC0AC\uD56D \uAC00\uC838\uC624\uAE30",
      "agentManager.intro.stage4.text": "\uC5D0\uC774\uC804\uD2B8\uC5D0\uAC8C pull request\uB97C \uC5F4\uB3C4\uB85D \uC694\uCCAD\uD558\uAC70\uB098 diff \uD328\uB110\uC5D0\uC11C Apply\uB97C \uC0AC\uC6A9\uD558\uC138\uC694.",
      "agentManager.intro.prDetection": "\uAC01 worktree \uBE0C\uB79C\uCE58\uC758 PR \uBC30\uC9C0\uAC00 \uC790\uB3D9\uC73C\uB85C \uC5C5\uB370\uC774\uD2B8\uB429\uB2C8\uB2E4(GitHub CLI \uB85C\uADF8\uC778 \uD544\uC694).",
      "agentManager.intro.checksRunning": "\uAC80\uC0AC \uC2E4\uD589 \uC911",
      "agentManager.intro.approved": "\uC2B9\uC778\uB428",
      "agentManager.intro.create": "worktree \uB9CC\uB4E4\uAE30",
      "agentManager.intro.guide": "\uAC00\uC774\uB4DC \uC77D\uAE30",
      "agentManager.intro.dismiss": "\uC18C\uAC1C \uAC74\uB108\uB6F0\uAE30",
      "agentManager.intro.reopen": "Agent Manager \uC791\uB3D9 \uBC29\uC2DD",
      "agentManager.worktree.health.absent-restorable": "\uD3F4\uB354 \uC0AD\uC81C\uB428",
      "agentManager.worktree.health.absent-restorableNote": "\uD3F4\uB354\uB294 \uC5C6\uC9C0\uB9CC \uBE0C\uB79C\uCE58 {{branch}}\uB294 \uB0A8\uC544 \uC788\uC2B5\uB2C8\uB2E4. \uBCF5\uC6D0\uD558\uBA74 \uACC4\uC18D \uC791\uC5C5\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.",
      "agentManager.worktree.health.absent-gone": "\uD3F4\uB354\uC640 \uBE0C\uB79C\uCE58 \uC0AD\uC81C\uB428",
      "agentManager.worktree.health.absent-goneNote": "\uD3F4\uB354\uC640 \uBE0C\uB79C\uCE58\uAC00 \uBAA8\uB450 \uC5C6\uC2B5\uB2C8\uB2E4. \uD56D\uBAA9\uC744 \uC81C\uAC70\uD574 \uC815\uB9AC\uD558\uC138\uC694. \uC138\uC158\uC740 \uB85C\uCEEC\uC5D0 \uBCF4\uC874\uB429\uB2C8\uB2E4.",
      "agentManager.worktree.health.unregistered": "git worktree \uC544\uB2D8",
      "agentManager.worktree.health.unregisteredNote": "\uD3F4\uB354\uB294 \uC788\uC9C0\uB9CC git\uC774 \uB354 \uC774\uC0C1 worktree\uB85C \uCD94\uC801\uD558\uC9C0 \uC54A\uC544 \uC0C1\uD0DC\uB97C \uC77D\uC744 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4.",
      "agentManager.worktree.health.unavailable": "\uC0C1\uD0DC\uB97C \uD655\uC778\uD560 \uC218 \uC5C6\uC74C",
      "agentManager.worktree.health.unavailableNote": "Git \uB610\uB294 GitHub CLI\uAC00 \uC81C\uB54C \uC751\uB2F5\uD558\uC9C0 \uC54A\uC558\uC2B5\uB2C8\uB2E4. \uC774 worktree\uC758 \uD3F4\uB9C1\uC744 \uC77C\uC2DC \uC911\uC9C0\uD588\uC73C\uBA70 \uB2E4\uC2DC \uC2DC\uB3C4\uD569\uB2C8\uB2E4.",
