      "settings.indexing.showButton.description": "\u041F\u043E\u043A\u0430\u0437\u044B\u0432\u0430\u0442\u044C \u043A\u043D\u043E\u043F\u043A\u0443 \u0438\u043D\u0434\u0435\u043A\u0441\u0430\u0446\u0438\u0438 \u043F\u043E\u0434 \u043F\u043E\u043B\u0435\u043C \u0432\u0432\u043E\u0434\u0430, \u043F\u043E\u043A\u0430 \u0438\u043D\u0434\u0435\u043A\u0441\u0430\u0446\u0438\u044F \u043E\u0442\u043A\u043B\u044E\u0447\u0435\u043D\u0430. \u0415\u0441\u043B\u0438 \u043A\u043D\u043E\u043F\u043A\u0430 \u0441\u043A\u0440\u044B\u0442\u0430, \u043E\u0442\u043A\u0440\u043E\u0439\u0442\u0435 \xAB\u041D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 > \u0418\u043D\u0434\u0435\u043A\u0441\u0430\u0446\u0438\u044F\xBB, \u0447\u0442\u043E\u0431\u044B \u0432\u043A\u043B\u044E\u0447\u0438\u0442\u044C \u0438\u043D\u0434\u0435\u043A\u0441\u0430\u0446\u0438\u044E.",
