      "settings.aboutKiloCode.importSettings.applied": "Settings imported and applied.",
      "settings.aboutKiloCode.telemetry.title": "\u0422\u0435\u043B\u0435\u043C\u0435\u0442\u0440\u0438\u044F",
      "settings.aboutKiloCode.telemetry.description": '\u0422\u0435\u043B\u0435\u043C\u0435\u0442\u0440\u0438\u044F \u0443\u043F\u0440\u0430\u0432\u043B\u044F\u0435\u0442\u0441\u044F \u0432\u0441\u0442\u0440\u043E\u0435\u043D\u043D\u043E\u0439 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u043E\u0439 \u0442\u0435\u043B\u0435\u043C\u0435\u0442\u0440\u0438\u0438 VS Code. \u0427\u0442\u043E\u0431\u044B \u043E\u0442\u043A\u043B\u044E\u0447\u0438\u0442\u044C \u0435\u0451, \u043F\u0435\u0440\u0435\u0439\u0434\u0438\u0442\u0435 \u0432 \u041D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 > \u0422\u0435\u043B\u0435\u043C\u0435\u0442\u0440\u0438\u044F > \u0423\u0440\u043E\u0432\u0435\u043D\u044C \u0442\u0435\u043B\u0435\u043C\u0435\u0442\u0440\u0438\u0438 \u0438 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u0435 \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u0435 "off". \u041F\u0435\u0440\u0435\u0437\u0430\u043F\u0443\u0441\u0442\u0438\u0442\u0435 VS Code, \u0447\u0442\u043E\u0431\u044B \u043F\u0440\u0438\u043C\u0435\u043D\u0438\u0442\u044C \u0438\u0437\u043C\u0435\u043D\u0435\u043D\u0438\u0435.',
      "settings.aboutKiloCode.telemetry.openSettings": "\u041E\u0442\u043A\u0440\u044B\u0442\u044C \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 \u0442\u0435\u043B\u0435\u043C\u0435\u0442\u0440\u0438\u0438",
