      "settings.agentBehaviour.sharedAgentBoard.title": "Kilo Swarm",
      "settings.agentBehaviour.sharedAgentBoard.description": "\u041F\u0440\u0435\u0434\u043E\u0441\u0442\u0430\u0432\u044C\u0442\u0435 \u043E\u0431\u0449\u0443\u044E \u0434\u043E\u0441\u043A\u0443 \u043E\u0441\u043D\u043E\u0432\u043D\u043E\u043C\u0443 \u0441\u0435\u0430\u043D\u0441\u0443 \u0438 \u0435\u0433\u043E \u043F\u043E\u0434\u0430\u0433\u0435\u043D\u0442\u0430\u043C, \u0432\u044B\u043F\u043E\u043B\u043D\u044F\u044E\u0449\u0438\u043C \u0437\u0430\u0434\u0430\u0447\u0438, \u0432\u043A\u043B\u044E\u0447\u0430\u044F \u0432\u043B\u043E\u0436\u0435\u043D\u043D\u044B\u0445 \u043F\u043E\u0434\u0430\u0433\u0435\u043D\u0442\u043E\u0432. \u0418\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0439\u0442\u0435 \u0435\u0451 \u0434\u043B\u044F \u043F\u0430\u0440\u0430\u043B\u043B\u0435\u043B\u044C\u043D\u044B\u0445 \u043F\u043E\u043F\u044B\u0442\u043E\u043A \u043D\u0430\u0439\u0442\u0438 \u0440\u0435\u0448\u0435\u043D\u0438\u0435 \u0438\u043B\u0438 \u0432\u0437\u0430\u0438\u043C\u043E\u0434\u043E\u043F\u043E\u043B\u043D\u044F\u044E\u0449\u0435\u0439 \u0440\u0430\u0431\u043E\u0442\u044B, \u0430 \u043D\u0435 \u0434\u043B\u044F \u043A\u0430\u0436\u0434\u043E\u0439 \u0437\u0430\u0434\u0430\u0447\u0438.",
      "settings.experimental.imageGenerationModel.title": "\u041C\u043E\u0434\u0435\u043B\u044C \u0438\u0437\u043E\u0431\u0440\u0430\u0436\u0435\u043D\u0438\u0439",
      "settings.experimental.imageGenerationModel.description": "\u041C\u043E\u0434\u0435\u043B\u044C \u0433\u0435\u043D\u0435\u0440\u0430\u0446\u0438\u0438 \u0438\u0437\u043E\u0431\u0440\u0430\u0436\u0435\u043D\u0438\u0439",
      "settings.experimental.imageGenerationModel.placeholder": "\u041F\u043E \u0443\u043C\u043E\u043B\u0447\u0430\u043D\u0438\u044E (Auto Router)",
      "settings.models.speechToTextModel.customDescription": "\u0418\u0434\u0435\u043D\u0442\u0438\u0444\u0438\u043A\u0430\u0442\u043E\u0440 \u043C\u043E\u0434\u0435\u043B\u0438, \u043E\u0442\u043F\u0440\u0430\u0432\u043B\u044F\u0435\u043C\u044B\u0439 \u0432 \u0432\u0430\u0448 \u0441\u043E\u0431\u0441\u0442\u0432\u0435\u043D\u043D\u044B\u0439 \u044D\u043D\u0434\u043F\u043E\u0438\u043D\u0442 \u0442\u0440\u0430\u043D\u0441\u043A\u0440\u0438\u043F\u0446\u0438\u0438, \u043D\u0430\u043F\u0440\u0438\u043C\u0435\u0440 whisper-1.",
      "settings.models.speechToTextModel.customPlaceholder": "whisper-1",
      "settings.models.speechToTextBaseUrl.title": "\u0411\u0430\u0437\u043E\u0432\u044B\u0439 URL \u0440\u0435\u0447\u0438 \u0432 \u0442\u0435\u043A\u0441\u0442",
      "settings.models.speechToTextBaseUrl.description": "\u0418\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u044C \u0441\u043E\u0432\u043C\u0435\u0441\u0442\u0438\u043C\u044B\u0439 \u0441 OpenAI API \u0442\u0440\u0430\u043D\u0441\u043A\u0440\u0438\u043F\u0446\u0438\u0438 \u0432\u043C\u0435\u0441\u0442\u043E Kilo Gateway. \u041C\u043E\u0434\u0435\u043B\u0438 \u0447\u0438\u0442\u0430\u044E\u0442\u0441\u044F \u0438\u0437 /models, \u0430\u0443\u0434\u0438\u043E \u043E\u0442\u043F\u0440\u0430\u0432\u043B\u044F\u0435\u0442\u0441\u044F \u0432 /audio/transcriptions. \u041E\u0441\u0442\u0430\u0432\u044C\u0442\u0435 \u043F\u0443\u0441\u0442\u044B\u043C, \u0447\u0442\u043E\u0431\u044B \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u044C Kilo Gateway.",
      "settings.models.speechToTextBaseUrl.placeholder": "https://api.openai.com/v1",
      "settings.models.speechToTextApiKey.title": "\u041A\u043B\u044E\u0447 API \u0440\u0435\u0447\u0438 \u0432 \u0442\u0435\u043A\u0441\u0442",
      "settings.models.speechToTextApiKey.description": "Bearer-\u0442\u043E\u043A\u0435\u043D, \u043E\u0442\u043F\u0440\u0430\u0432\u043B\u044F\u0435\u043C\u044B\u0439 \u043D\u0430 \u0441\u043E\u0431\u0441\u0442\u0432\u0435\u043D\u043D\u044B\u0439 \u0431\u0430\u0437\u043E\u0432\u044B\u0439 URL \u0442\u0440\u0430\u043D\u0441\u043A\u0440\u0438\u043F\u0446\u0438\u0438. \u0425\u0440\u0430\u043D\u0438\u0442\u0441\u044F \u0432 \u0444\u0430\u0439\u043B\u0435 \u043A\u043E\u043D\u0444\u0438\u0433\u0443\u0440\u0430\u0446\u0438\u0438 Kilo.",
      "settings.models.speechToTextApiKey.placeholder": "sk-...",
      "settings.models.speechToText.disabledDescription": "\u0412\u043A\u043B\u044E\u0447\u0438\u0442\u0435 \u043F\u0440\u043E\u0432\u0430\u0439\u0434\u0435\u0440 Kilo \u0438 \u0432\u044B\u043F\u043E\u043B\u043D\u0438\u0442\u0435 \u0432\u0445\u043E\u0434, \u0447\u0442\u043E\u0431\u044B \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u044C Speech to Text, \u043B\u0438\u0431\u043E \u0443\u043A\u0430\u0436\u0438\u0442\u0435 \u043D\u0438\u0436\u0435 \u0441\u0432\u043E\u0439 \u0431\u0430\u0437\u043E\u0432\u044B\u0439 URL \u0442\u0440\u0430\u043D\u0441\u043A\u0440\u0438\u043F\u0446\u0438\u0438.",
      "settings.models.speechToText.remoteDescription": "\u0413\u043E\u043B\u043E\u0441\u043E\u0432\u043E\u0439 \u0432\u0432\u043E\u0434 \u043D\u0435\u0434\u043E\u0441\u0442\u0443\u043F\u0435\u043D \u0432 \u0443\u0434\u0430\u043B\u0451\u043D\u043D\u044B\u0445 \u043E\u043A\u043D\u0430\u0445. \u041E\u0442\u043A\u0440\u043E\u0439\u0442\u0435 Kilo \u0432 \u043B\u043E\u043A\u0430\u043B\u044C\u043D\u043E\u043C \u043E\u043A\u043D\u0435, \u0447\u0442\u043E\u0431\u044B \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u044C \u043C\u0438\u043A\u0440\u043E\u0444\u043E\u043D.",
      "settings.models.speechToTextModel.title": "\u041C\u043E\u0434\u0435\u043B\u044C \u0440\u0435\u0447\u0438 \u0432 \u0442\u0435\u043A\u0441\u0442",
      "settings.models.speechToTextModel.description": "\u0412\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u043C\u043E\u0434\u0435\u043B\u044C \u0442\u0440\u0430\u043D\u0441\u043A\u0440\u0438\u043F\u0446\u0438\u0438 Kilo Gateway \u0434\u043B\u044F \u0433\u043E\u043B\u043E\u0441\u043E\u0432\u043E\u0433\u043E \u0432\u0432\u043E\u0434\u0430.",
      "settings.experimental.nativeNotebookTools.title": "\u041D\u0430\u0442\u0438\u0432\u043D\u044B\u0435 \u0438\u043D\u0441\u0442\u0440\u0443\u043C\u0435\u043D\u0442\u044B \u0431\u043B\u043E\u043A\u043D\u043E\u0442\u043E\u0432",
      "settings.experimental.nativeNotebookTools.description": "\u0412\u043A\u043B\u044E\u0447\u0438\u0442\u044C \u044D\u043A\u0441\u043F\u0435\u0440\u0438\u043C\u0435\u043D\u0442\u0430\u043B\u044C\u043D\u044B\u0435 \u0438\u043D\u0441\u0442\u0440\u0443\u043C\u0435\u043D\u0442\u044B \u0434\u043B\u044F \u0447\u0442\u0435\u043D\u0438\u044F, \u0440\u0435\u0434\u0430\u043A\u0442\u0438\u0440\u043E\u0432\u0430\u043D\u0438\u044F \u0438 \u0432\u044B\u043F\u043E\u043B\u043D\u0435\u043D\u0438\u044F \u0431\u043B\u043E\u043A\u043D\u043E\u0442\u043E\u0432 VS Code",
      "settings.experimental.globIncludeIgnored.title": "\u041F\u043E\u0438\u0441\u043A \u0432 \u0438\u0433\u043D\u043E\u0440\u0438\u0440\u0443\u0435\u043C\u044B\u0445 \u043F\u0443\u0442\u044F\u0445",
      "settings.experimental.globIncludeIgnored.description": "\u041F\u0430\u043F\u043A\u0438 \u0438\u043B\u0438 \u0444\u0430\u0439\u043B\u044B, \u0432 \u043A\u043E\u0442\u043E\u0440\u044B\u0445 \u0438\u043D\u0441\u0442\u0440\u0443\u043C\u0435\u043D\u0442 glob \u0434\u043E\u043B\u0436\u0435\u043D \u0438\u0441\u043A\u0430\u0442\u044C, \u0434\u0430\u0436\u0435 \u0435\u0441\u043B\u0438 \u0438\u0445 \u0438\u0441\u043A\u043B\u044E\u0447\u0430\u0435\u0442 .gitignore \u0438\u043B\u0438 \u0434\u0440\u0443\u0433\u0438\u0435 ignore-\u0444\u0430\u0439\u043B\u044B. \u0418\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0439\u0442\u0435 \u0448\u0430\u0431\u043B\u043E\u043D\u044B \u0432 \u0441\u0442\u0438\u043B\u0435 gitignore \u043E\u0442\u043D\u043E\u0441\u0438\u0442\u0435\u043B\u044C\u043D\u043E \u0440\u0430\u0431\u043E\u0447\u0435\u0439 \u043E\u0431\u043B\u0430\u0441\u0442\u0438; \u0438\u0433\u043D\u043E\u0440\u0438\u0440\u0443\u0435\u043C\u044B\u0435 \u043F\u0430\u043F\u043A\u0438 \u0432\u043D\u0443\u0442\u0440\u0438 \u043D\u0438\u0445 \u043F\u043E-\u043F\u0440\u0435\u0436\u043D\u0435\u043C\u0443 \u043F\u0440\u043E\u043F\u0443\u0441\u043A\u0430\u044E\u0442\u0441\u044F.",
      "settings.experimental.continueOnDeny.title": "\u041F\u0440\u043E\u0434\u043E\u043B\u0436\u0438\u0442\u044C \u043F\u0440\u0438 \u043E\u0442\u043A\u0430\u0437\u0435",
