      "settings.agentBehaviour.permissions.col.tool": "\u0418\u043D\u0441\u0442\u0440\u0443\u043C\u0435\u043D\u0442",
      "settings.agentBehaviour.permissions.col.pattern": "\u0428\u0430\u0431\u043B\u043E\u043D",
      "settings.agentBehaviour.permissions.col.action": "\u0414\u0435\u0439\u0441\u0442\u0432\u0438\u0435",
      "settings.agentBehaviour.permissions.copy": "\u0421\u043A\u043E\u043F\u0438\u0440\u043E\u0432\u0430\u0442\u044C \u0440\u0430\u0437\u0440\u0435\u0448\u0435\u043D\u0438\u044F \u043A\u0430\u043A JSON",
      "settings.agentBehaviour.permissions.hint": "\u041F\u0440\u0430\u0432\u0438\u043B\u0430 \u043E\u0446\u0435\u043D\u0438\u0432\u0430\u044E\u0442\u0441\u044F \u043F\u043E \u043F\u043E\u0440\u044F\u0434\u043A\u0443 \u2014 \u043F\u043E\u0431\u0435\u0436\u0434\u0430\u0435\u0442 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0435\u0435 \u0441\u043E\u0432\u043F\u0430\u0432\u0448\u0435\u0435 \u043F\u0440\u0430\u0432\u0438\u043B\u043E. \u042D\u0442\u043E \u0440\u0430\u0437\u0440\u0435\u0448\u0435\u043D\u043D\u044B\u0439 \u043D\u0430\u0431\u043E\u0440 \u043F\u0440\u0430\u0432\u0438\u043B \u0438\u0437 \u0431\u044D\u043A\u0435\u043D\u0434\u0430 CLI.",
      "settings.agentBehaviour.removeAgent.title": "\u0423\u0434\u0430\u043B\u0438\u0442\u044C \u0430\u0433\u0435\u043D\u0442",
      "settings.agentBehaviour.removeAgent.confirm": '\u0423\u0434\u0430\u043B\u0438\u0442\u044C \u0430\u0433\u0435\u043D\u0442 "{{name}}"? \u042D\u0442\u043E \u043E\u0442\u043A\u043B\u044E\u0447\u0438\u0442 \u0430\u0433\u0435\u043D\u0442, \u043E\u0431\u043D\u043E\u0432\u0438\u0432 \u043A\u043E\u043D\u0444\u0438\u0433\u0443\u0440\u0430\u0446\u0438\u044E.',
      "settings.agentBehaviour.removeAgent.button": "\u0423\u0434\u0430\u043B\u0438\u0442\u044C",
      "settings.agentBehaviour.removeMcp.title": "\u0423\u0434\u0430\u043B\u0438\u0442\u044C \u0441\u0435\u0440\u0432\u0435\u0440 MCP",
      "settings.agentBehaviour.removeMcp.confirm": '\u0423\u0434\u0430\u043B\u0438\u0442\u044C \u0441\u0435\u0440\u0432\u0435\u0440 MCP "{{name}}"? \u042D\u0442\u043E \u0443\u0434\u0430\u043B\u0438\u0442 \u0435\u0433\u043E \u0438\u0437 \u0432\u0430\u0448\u0435\u0439 \u043A\u043E\u043D\u0444\u0438\u0433\u0443\u0440\u0430\u0446\u0438\u0438.',
      "settings.agentBehaviour.removeMcp.bundleConfirm": '\u0423\u0434\u0430\u043B\u0438\u0442\u044C \u0441\u0435\u0440\u0432\u0435\u0440 MCP "{{name}}" \u0438 \u0441\u043E\u043F\u0443\u0442\u0441\u0442\u0432\u0443\u044E\u0449\u0438\u0435 \u043D\u0430\u0432\u044B\u043A\u0438? \u042D\u0442\u043E \u0443\u0434\u0430\u043B\u0438\u0442 \u043A\u0430\u043A \u0441\u0435\u0440\u0432\u0435\u0440, \u0442\u0430\u043A \u0438 \u043A\u0430\u0436\u0434\u044B\u0439 \u043D\u0430\u0432\u044B\u043A, \u043F\u0440\u0438\u043D\u0430\u0434\u043B\u0435\u0436\u0430\u0449\u0438\u0439 \u044D\u0442\u043E\u0439 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0435 Marketplace.',
      "settings.agentBehaviour.removeMcp.button": "\u0423\u0434\u0430\u043B\u0438\u0442\u044C",
      "settings.agentBehaviour.editMcp": "\u0420\u0435\u0434\u0430\u043A\u0442\u0438\u0440\u043E\u0432\u0430\u0442\u044C \u0441\u0435\u0440\u0432\u0435\u0440 MCP",
      "settings.agentBehaviour.editMcp.transportLocal": "\u041B\u043E\u043A\u0430\u043B\u044C\u043D\u044B\u0439 \u0441\u0435\u0440\u0432\u0435\u0440 (\u0442\u0440\u0430\u043D\u0441\u043F\u043E\u0440\u0442 stdio)",
      "settings.agentBehaviour.editMcp.transportRemote": "\u0423\u0434\u0430\u043B\u0451\u043D\u043D\u044B\u0439 \u0441\u0435\u0440\u0432\u0435\u0440 (\u0442\u0440\u0430\u043D\u0441\u043F\u043E\u0440\u0442 SSE/HTTP)",
      "settings.agentBehaviour.editMcp.env": "\u041F\u0435\u0440\u0435\u043C\u0435\u043D\u043D\u044B\u0435 \u043E\u043A\u0440\u0443\u0436\u0435\u043D\u0438\u044F",
      "settings.agentBehaviour.editMcp.env.help": "\u041F\u0435\u0440\u0435\u043C\u0435\u043D\u043D\u044B\u0435, \u043F\u0435\u0440\u0435\u0434\u0430\u0432\u0430\u0435\u043C\u044B\u0435 \u043F\u0440\u043E\u0446\u0435\u0441\u0441\u0443 \u0441\u0435\u0440\u0432\u0435\u0440\u0430 MCP.",
      "settings.agentBehaviour.editMcp.oauth": "OAuth",
      "settings.agentBehaviour.editMcp.oauth.help": "\u041E\u0441\u0442\u0430\u0432\u044C\u0442\u0435 \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u0435 \u0410\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438, \u0435\u0441\u043B\u0438 \u0441\u0435\u0440\u0432\u0435\u0440 \u043D\u0435 \u0442\u0440\u0435\u0431\u0443\u0435\u0442 \u043F\u0440\u0435\u0434\u0432\u0430\u0440\u0438\u0442\u0435\u043B\u044C\u043D\u043E \u0437\u0430\u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0438\u0440\u043E\u0432\u0430\u043D\u043D\u043E\u0433\u043E \u043A\u043B\u0438\u0435\u043D\u0442\u0430. \u0421\u0435\u043A\u0440\u0435\u0442 \u043A\u043B\u0438\u0435\u043D\u0442\u0430 \u0445\u0440\u0430\u043D\u0438\u0442\u0441\u044F \u0432 \u0432\u0430\u0448\u0435\u043C \u0444\u0430\u0439\u043B\u0435 \u043A\u043E\u043D\u0444\u0438\u0433\u0443\u0440\u0430\u0446\u0438\u0438 Kilo.",
