      "settings.agentBehaviour.skillPaths": "\u041F\u0443\u0442\u0438 \u043F\u0430\u043F\u043E\u043A \u043D\u0430\u0432\u044B\u043A\u043E\u0432",
      "settings.agentBehaviour.skillUrls": "URL \u043D\u0430\u0432\u044B\u043A\u043E\u0432",
      "settings.agentBehaviour.removeSkill.title": "\u0423\u0434\u0430\u043B\u0438\u0442\u044C \u043D\u0430\u0432\u044B\u043A",
      "settings.agentBehaviour.removeSkill.confirm": '\u0423\u0434\u0430\u043B\u0438\u0442\u044C \u043D\u0430\u0432\u044B\u043A "{{name}}"? \u042D\u0442\u043E \u043F\u0440\u0438\u0432\u0435\u0434\u0435\u0442 \u043A \u0443\u0434\u0430\u043B\u0435\u043D\u0438\u044E \u0444\u0430\u0439\u043B\u043E\u0432 \u043D\u0430\u0432\u044B\u043A\u0430 \u0441 \u0434\u0438\u0441\u043A\u0430.',
      "settings.agentBehaviour.removeSkill.bundleConfirm": '\u0423\u0434\u0430\u043B\u0438\u0442\u044C \u043D\u0430\u0432\u044B\u043A "{{name}}"? \u042D\u0442\u043E \u0442\u0430\u043A\u0436\u0435 \u0443\u0434\u0430\u043B\u0438\u0442 \u0441\u0435\u0440\u0432\u0435\u0440 MCP {{mcp}} \u0438 \u043A\u0430\u0436\u0434\u044B\u0439 \u0441\u043E\u043F\u0443\u0442\u0441\u0442\u0432\u0443\u044E\u0449\u0438\u0439 \u043D\u0430\u0432\u044B\u043A \u0438\u0437 \u0442\u043E\u0439 \u0436\u0435 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0438 Marketplace.',
      "settings.agentBehaviour.removeSkill.button": "\u0423\u0434\u0430\u043B\u0438\u0442\u044C",
      "settings.agentBehaviour.rules.description": "\u041F\u0440\u0430\u0432\u0438\u043B\u0430 \u2014 \u044D\u0442\u043E \u0444\u0430\u0439\u043B\u044B \u0438\u043D\u0441\u0442\u0440\u0443\u043A\u0446\u0438\u0439, \u043A\u043E\u0442\u043E\u0440\u044B\u0435 \u043D\u0430\u043F\u0440\u0430\u0432\u043B\u044F\u044E\u0442 \u043F\u043E\u0432\u0435\u0434\u0435\u043D\u0438\u0435 \u0430\u0433\u0435\u043D\u0442\u0430. \u041E\u043D\u0438 \u0432\u043A\u043B\u044E\u0447\u0430\u044E\u0442\u0441\u044F \u0432 \u0441\u0438\u0441\u0442\u0435\u043C\u043D\u044B\u0439 \u043F\u0440\u043E\u043C\u043F\u0442 \u0434\u043B\u044F \u043A\u0430\u0436\u0434\u043E\u0433\u043E \u0440\u0430\u0437\u0433\u043E\u0432\u043E\u0440\u0430. \u0414\u043E\u0431\u0430\u0432\u044C\u0442\u0435 \u043F\u0443\u0442\u0438 \u043A \u0444\u0430\u0439\u043B\u0430\u043C \u043D\u0438\u0436\u0435, \u0447\u0442\u043E\u0431\u044B \u0432\u043A\u043B\u044E\u0447\u0438\u0442\u044C \u0434\u043E\u043F\u043E\u043B\u043D\u0438\u0442\u0435\u043B\u044C\u043D\u044B\u0435 \u043F\u0440\u0430\u0432\u0438\u043B\u0430.",
      "settings.agentBehaviour.instructionFiles": "\u0414\u043E\u043F\u043E\u043B\u043D\u0438\u0442\u0435\u043B\u044C\u043D\u044B\u0435 \u0444\u0430\u0439\u043B\u044B \u0438\u043D\u0441\u0442\u0440\u0443\u043A\u0446\u0438\u0439",
      "settings.agentBehaviour.instructionFiles.description": "\u041F\u0443\u0442\u0438 \u043A \u0434\u043E\u043F\u043E\u043B\u043D\u0438\u0442\u0435\u043B\u044C\u043D\u044B\u043C \u0444\u0430\u0439\u043B\u0430\u043C \u0438\u043D\u0441\u0442\u0440\u0443\u043A\u0446\u0438\u0439 \u0432 \u0441\u0438\u0441\u0442\u0435\u043C\u043D\u043E\u043C \u043F\u0440\u043E\u043C\u043F\u0442\u0435",
      "settings.agentBehaviour.pushFixes.title": "\u041E\u0442\u043F\u0440\u0430\u0432\u043B\u044F\u0442\u044C \u0438\u0441\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u044F \u043F\u0443\u043B-\u0440\u0435\u043A\u0432\u0435\u0441\u0442\u0430",
      "settings.agentBehaviour.pushFixes.description": "\u041A\u043E\u0433\u0434\u0430 \u0432\u044B \u043E\u0442\u043F\u0440\u0430\u0432\u043B\u044F\u0435\u0442\u0435 \u0430\u0433\u0435\u043D\u0442\u0443 \u043E\u0448\u0438\u0431\u043A\u0438 CI \u0438\u043B\u0438 \u043A\u043E\u043C\u043C\u0435\u043D\u0442\u0430\u0440\u0438\u0438 \u0440\u0435\u0432\u044C\u044E \u0438\u0437 \u043F\u0443\u043B-\u0440\u0435\u043A\u0432\u0435\u0441\u0442\u0430 \u043B\u0438\u0431\u043E \u043E\u0431\u043D\u043E\u0432\u043B\u044F\u0435\u0442\u0435 worktree \u0438\u0437 \u0431\u0430\u0437\u043E\u0432\u043E\u0439 \u0432\u0435\u0442\u043A\u0438, \u043F\u043E\u043F\u0440\u043E\u0441\u0438\u0442\u044C \u0435\u0433\u043E \u0441\u0434\u0435\u043B\u0430\u0442\u044C \u043A\u043E\u043C\u043C\u0438\u0442 \u0438 push, \u0447\u0442\u043E\u0431\u044B \u043F\u0443\u043B-\u0440\u0435\u043A\u0432\u0435\u0441\u0442 \u043E\u0431\u043D\u043E\u0432\u0438\u043B\u0441\u044F. \u0417\u0430\u043F\u0440\u043E\u0441\u044B \u0440\u0430\u0437\u0440\u0435\u0448\u0435\u043D\u0438\u0439 \u043F\u043E-\u043F\u0440\u0435\u0436\u043D\u0435\u043C\u0443 \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u044E\u0442. \u041E\u0442\u043A\u043B\u044E\u0447\u0438\u0442\u0435, \u0447\u0442\u043E\u0431\u044B \u0434\u0435\u043B\u0430\u0442\u044C \u043A\u043E\u043C\u043C\u0438\u0442\u044B \u0432\u0440\u0443\u0447\u043D\u0443\u044E.",
      "settings.agentBehaviour.claudeCompat.heading": "\u0421\u043E\u0432\u043C\u0435\u0441\u0442\u0438\u043C\u043E\u0441\u0442\u044C \u0441 Claude Code",
      "settings.agentBehaviour.claudeCompat.title": "\u0417\u0430\u0433\u0440\u0443\u0436\u0430\u0442\u044C \u0444\u0430\u0439\u043B\u044B Claude Code",
      "settings.agentBehaviour.claudeCompat.description": "\u0417\u0430\u0433\u0440\u0443\u0436\u0430\u0442\u044C \u0438\u043D\u0441\u0442\u0440\u0443\u043A\u0446\u0438\u0438 CLAUDE.md \u0438 \u043D\u0430\u0432\u044B\u043A\u0438 \u0438\u0437 \u043A\u0430\u0442\u0430\u043B\u043E\u0433\u0430 \u043A\u043E\u043D\u0444\u0438\u0433\u0443\u0440\u0430\u0446\u0438\u0438 Claude Code \u0432 \u0441\u0435\u0441\u0441\u0438\u0438. \u0412\u043A\u043B\u044E\u0447\u0438\u0442\u0435 \u044D\u0442\u0443 \u043E\u043F\u0446\u0438\u044E, \u0435\u0441\u043B\u0438 \u0445\u043E\u0442\u0438\u0442\u0435, \u0447\u0442\u043E\u0431\u044B Kilo \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u043B \u0432\u0430\u0448\u0438 \u0438\u043D\u0441\u0442\u0440\u0443\u043A\u0446\u0438\u0438 \u0438 \u043D\u0430\u0432\u044B\u043A\u0438 Claude Code. \u0422\u0440\u0435\u0431\u0443\u0435\u0442\u0441\u044F \u043F\u0435\u0440\u0435\u0437\u0430\u043F\u0443\u0441\u043A.",
      "settings.agentBehaviour.mcpDetail.command": "\u041A\u043E\u043C\u0430\u043D\u0434\u0430",
      "settings.agentBehaviour.mcpDetail.args": "\u0410\u0440\u0433\u0443\u043C\u0435\u043D\u0442\u044B",
      "settings.agentBehaviour.mcpDetail.env": "\u041E\u043A\u0440\u0443\u0436\u0435\u043D\u0438\u0435",
