      "settings.agentBehaviour.mcpResetAuth.confirm": '\u041E\u0447\u0438\u0441\u0442\u0438\u0442\u044C \u0441\u043E\u0445\u0440\u0430\u043D\u0435\u043D\u043D\u044B\u0435 \u0434\u0430\u043D\u043D\u044B\u0435 \u0432\u0445\u043E\u0434\u0430 \u0434\u043B\u044F "{{name}}"? \u0412\u0430\u043C \u043D\u0443\u0436\u043D\u043E \u0431\u0443\u0434\u0435\u0442 \u0432\u043E\u0439\u0442\u0438 \u0441\u043D\u043E\u0432\u0430.',
