      "settings.agentBehaviour.mcpEmpty": "MCP-\u0441\u0435\u0440\u0432\u0435\u0440\u044B \u043D\u0435 \u043D\u0430\u0441\u0442\u0440\u043E\u0435\u043D\u044B. \u0414\u043E\u0431\u0430\u0432\u044C\u0442\u0435 MCP-\u0441\u0435\u0440\u0432\u0435\u0440\u044B \u0432 kilo2.json \u0438\u043B\u0438 \u043F\u043E\u043F\u0440\u043E\u0441\u0438\u0442\u0435 \u0430\u0433\u0435\u043D\u0442\u0430 \u0434\u043E\u0431\u0430\u0432\u0438\u0442\u044C \u0438\u0445.",
      "settings.agentBehaviour.workflows.description": "\u0420\u0430\u0431\u043E\u0447\u0438\u0435 \u043F\u0440\u043E\u0446\u0435\u0441\u0441\u044B: \u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u0435\u043B\u044C\u0441\u043A\u0438\u0435 \u043A\u043E\u043C\u0430\u043D\u0434\u044B, \u043E\u043F\u0440\u0435\u0434\u0435\u043B\u0451\u043D\u043D\u044B\u0435 \u0432 \u0432\u0430\u0448\u0435\u0439 \u043A\u043E\u043D\u0444\u0438\u0433\u0443\u0440\u0430\u0446\u0438\u0438 \u0438\u043B\u0438 \u0432 \u0444\u0430\u0439\u043B\u0430\u0445 Markdown \u0441 \u043A\u043E\u043C\u0430\u043D\u0434\u0430\u043C\u0438. \u0414\u043B\u044F \u043A\u0430\u0436\u0434\u043E\u0433\u043E \u0440\u0430\u0431\u043E\u0447\u0435\u0433\u043E \u043F\u0440\u043E\u0446\u0435\u0441\u0441\u0430 \u043C\u043E\u0436\u043D\u043E \u0437\u0430\u0434\u0430\u0442\u044C \u043C\u043E\u0434\u0435\u043B\u044C \u0438 \u0432\u0430\u0440\u0438\u0430\u043D\u0442 \u0440\u0430\u0441\u0441\u0443\u0436\u0434\u0435\u043D\u0438\u044F.",
      "settings.agentBehaviour.workflows.empty": "\u041F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u0435\u043B\u044C\u0441\u043A\u0438\u0435 \u043A\u043E\u043C\u0430\u043D\u0434\u044B \u043D\u0435 \u043D\u0430\u0439\u0434\u0435\u043D\u044B. \u0414\u043E\u0431\u0430\u0432\u044C\u0442\u0435 \u043A\u043E\u043C\u0430\u043D\u0434\u044B \u0432 kilo2.json \u0438\u043B\u0438 \u0432 \u0444\u0430\u0439\u043B Markdown \u0432 .kilo2/command.",
