      "settings.display.codeMode.description": "\u0412\u044B\u0431\u0435\u0440\u0438\u0442\u0435, \u0431\u0443\u0434\u0443\u0442 \u043B\u0438 \u0431\u043B\u043E\u043A\u0438 Code Mode \u043D\u0430\u0447\u0438\u043D\u0430\u0442\u044C\u0441\u044F \u0441\u043E \u0441\u043F\u0438\u0441\u043A\u0430 \u0432\u044B\u0437\u043E\u0432\u043E\u0432 \u0438\u043D\u0441\u0442\u0440\u0443\u043C\u0435\u043D\u0442\u043E\u0432 \u0438\u043B\u0438 \u0441 \u043E\u0434\u043D\u043E\u0439 \u0441\u0442\u0440\u043E\u043A\u0438. \u0421\u043A\u0440\u0438\u043F\u0442 \u0432\u0441\u0435\u0433\u0434\u0430 \u043E\u0441\u0442\u0430\u0451\u0442\u0441\u044F \u0441\u043A\u0440\u044B\u0442\u044B\u043C, \u043F\u043E\u043A\u0430 \u0432\u044B \u0435\u0433\u043E \u043D\u0435 \u043E\u0442\u043A\u0440\u043E\u0435\u0442\u0435.",
