      "settings.display.shortcutHints.description": "\u041F\u043E\u043A\u0430\u0437\u044B\u0432\u0430\u0442\u044C \u0432 \u043F\u0443\u0441\u0442\u043E\u043C \u043F\u043E\u043B\u0435 \u0437\u0430\u043F\u0440\u043E\u0441\u0430 \u0441\u043E\u0447\u0435\u0442\u0430\u043D\u0438\u0435 \u043A\u043B\u0430\u0432\u0438\u0448, \u043F\u043E\u0434\u0445\u043E\u0434\u044F\u0449\u0435\u0435 \u043A \u0442\u0435\u043A\u0443\u0449\u0435\u043C\u0443 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044E, \u043D\u0430\u043F\u0440\u0438\u043C\u0435\u0440 \u043A\u0430\u043A \u0434\u043E\u0431\u0430\u0432\u0438\u0442\u044C \u0432\u044B\u0434\u0435\u043B\u0435\u043D\u043D\u044B\u0439 \u043A\u043E\u0434 \u0438\u043B\u0438 \u0432\u0435\u0440\u043D\u0443\u0442\u044C\u0441\u044F \u043A \u0437\u0430\u043F\u0440\u043E\u0441\u0443.",
