      "diffViewer.source.workspace.tooltip": "\u0412\u0441\u0435 \u0438\u0437\u043C\u0435\u043D\u0435\u043D\u0438\u044F \u0432 \u044D\u0442\u043E\u0439 \u0432\u0435\u0442\u043A\u0435 \u043F\u043E \u0441\u0440\u0430\u0432\u043D\u0435\u043D\u0438\u044E \u0441 \u0431\u0430\u0437\u043E\u0432\u043E\u0439. \u0412\u043A\u043B\u044E\u0447\u0430\u0435\u0442 \u043D\u0435\u0437\u0430\u043A\u043E\u043C\u043C\u0438\u0447\u0435\u043D\u043D\u044B\u0435 \u0444\u0430\u0439\u043B\u044B (staged, unstaged, \u043D\u0435\u043E\u0442\u0441\u043B\u0435\u0436\u0438\u0432\u0430\u0435\u043C\u044B\u0435) \u0438 \u043B\u043E\u043A\u0430\u043B\u044C\u043D\u044B\u0435 \u043A\u043E\u043C\u043C\u0438\u0442\u044B, \u043A\u043E\u0442\u043E\u0440\u044B\u0445 \u0435\u0449\u0451 \u043D\u0435\u0442 \u0432 \u0431\u0430\u0437\u0435.",
      "diffViewer.source.staged.label": "\u041F\u0440\u043E\u0438\u043D\u0434\u0435\u043A\u0441\u0438\u0440\u043E\u0432\u0430\u043D\u043E",
      "diffViewer.source.staged.tooltip": "\u0424\u0430\u0439\u043B\u044B \u0441 \u0438\u0437\u043C\u0435\u043D\u0435\u043D\u0438\u044F\u043C\u0438, \u0434\u043E\u0431\u0430\u0432\u043B\u0435\u043D\u043D\u044B\u0435 \u0432 \u0438\u043D\u0434\u0435\u043A\u0441 git (`git add`), \u043A\u0430\u043A \u043E\u043D\u0438 \u043F\u043E\u044F\u0432\u044F\u0442\u0441\u044F \u0432 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u043C \u043A\u043E\u043C\u043C\u0438\u0442\u0435.",
