      "agentManager.settings.autoBranchNaming.description": "\u0410\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438 \u0438\u043C\u0435\u043D\u043E\u0432\u0430\u0442\u044C \u0432\u0435\u0442\u043A\u0438, \u043A\u043E\u0433\u0434\u0430 \u0432 \u0440\u0430\u0437\u0433\u043E\u0432\u043E\u0440\u0435 \u043E\u043F\u0438\u0441\u0430\u043D\u0430 \u0447\u0451\u0442\u043A\u0430\u044F \u0437\u0430\u0434\u0430\u0447\u0430. \u041F\u0440\u0438\u043C\u0435\u043D\u044F\u0435\u0442\u0441\u044F \u043A\u043E \u0432\u0441\u0435\u043C \u043F\u0440\u043E\u0435\u043A\u0442\u0430\u043C. \u0412\u0435\u0442\u043A\u0438 \u0441 \u044F\u0432\u043D\u043E \u0437\u0430\u0434\u0430\u043D\u043D\u044B\u043C\u0438 \u0438\u043C\u0435\u043D\u0430\u043C\u0438 \u0438 \u043E\u043F\u0443\u0431\u043B\u0438\u043A\u043E\u0432\u0430\u043D\u043D\u044B\u0435 \u0432\u0435\u0442\u043A\u0438 \u043D\u0438\u043A\u043E\u0433\u0434\u0430 \u043D\u0435 \u043F\u0435\u0440\u0435\u0438\u043C\u0435\u043D\u043E\u0432\u044B\u0432\u0430\u044E\u0442\u0441\u044F.",
      "agentManager.settings.branchPrefix.title": "\u041F\u0440\u0435\u0444\u0438\u043A\u0441 \u0432\u0435\u0442\u043A\u0438",
      "agentManager.settings.branchPrefix.description": "\u041F\u0440\u0435\u0444\u0438\u043A\u0441 \u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438 \u0438\u043C\u0435\u043D\u0443\u0435\u043C\u044B\u0445 \u0432\u0435\u0442\u043E\u043A \u0432\u043E \u0432\u0441\u0435\u0445 \u043F\u0440\u043E\u0435\u043A\u0442\u0430\u0445, \u043D\u0430\u043F\u0440\u0438\u043C\u0435\u0440 feature/. \u041D\u0435 \u043F\u0440\u0438\u043C\u0435\u043D\u044F\u0435\u0442\u0441\u044F \u043A \u044F\u0432\u043D\u043E \u0437\u0430\u0434\u0430\u043D\u043D\u044B\u043C \u0438\u043C\u0435\u043D\u0430\u043C \u0432\u0435\u0442\u043E\u043A. \u041E\u0441\u0442\u0430\u0432\u044C\u0442\u0435 \u043F\u0443\u0441\u0442\u044B\u043C, \u0447\u0442\u043E\u0431\u044B \u043D\u0435 \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u044C \u043F\u0440\u0435\u0444\u0438\u043A\u0441.",
      "agentManager.settings.worktreePool.title": "\u041F\u0440\u0435\u0434\u0432\u0430\u0440\u0438\u0442\u0435\u043B\u044C\u043D\u044B\u0439 \u043F\u0440\u043E\u0433\u0440\u0435\u0432 worktree",
      "agentManager.settings.worktreePool.description": "\u041F\u043E\u0434\u0433\u043E\u0442\u043E\u0432\u044C\u0442\u0435 \u0433\u043E\u0442\u043E\u0432\u044B\u0439 worktree \u0432 \u0444\u043E\u043D\u0435, \u0447\u0442\u043E\u0431\u044B \u043D\u043E\u0432\u044B\u0435 \u0441\u0435\u0441\u0441\u0438\u0438 Agent Manager \u0437\u0430\u043F\u0443\u0441\u043A\u0430\u043B\u0438\u0441\u044C \u0431\u044B\u0441\u0442\u0440\u0435\u0435. \u0418\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0435\u0442 \u0434\u043E\u043F\u043E\u043B\u043D\u0438\u0442\u0435\u043B\u044C\u043D\u043E\u0435 \u043C\u0435\u0441\u0442\u043E \u043D\u0430 \u0434\u0438\u0441\u043A\u0435 \u0434\u043B\u044F \u043E\u0434\u043D\u043E\u0433\u043E checkout \u043D\u0430 \u043A\u0430\u0436\u0434\u044B\u0439 \u043E\u0442\u043A\u0440\u044B\u0442\u044B\u0439 \u043F\u0440\u043E\u0435\u043A\u0442.",
