      "agentManager.orphans.checkoutWarning": "\u0441\u043E\u0434\u0435\u0440\u0436\u0438\u0442 \u0440\u0430\u0431\u043E\u0447\u0443\u044E \u043A\u043E\u043F\u0438\u044E git",
