      "settings.agentBehaviour.exportMode": "\u0E2A\u0E48\u0E07\u0E2D\u0E2D\u0E01\u0E19\u0E34\u0E22\u0E32\u0E21\u0E40\u0E2D\u0E40\u0E08\u0E19\u0E15\u0E4C",
