      "settings.agentBehaviour.editMcp.oauth": "OAuth",
      "settings.agentBehaviour.editMcp.oauth.help": "\u0E1B\u0E25\u0E48\u0E2D\u0E22\u0E44\u0E27\u0E49\u0E17\u0E35\u0E48\u0E2D\u0E31\u0E15\u0E42\u0E19\u0E21\u0E31\u0E15\u0E34 \u0E40\u0E27\u0E49\u0E19\u0E41\u0E15\u0E48\u0E40\u0E0B\u0E34\u0E23\u0E4C\u0E1F\u0E40\u0E27\u0E2D\u0E23\u0E4C\u0E15\u0E49\u0E2D\u0E07\u0E01\u0E32\u0E23\u0E44\u0E04\u0E25\u0E40\u0E2D\u0E47\u0E19\u0E15\u0E4C\u0E17\u0E35\u0E48\u0E25\u0E07\u0E17\u0E30\u0E40\u0E1A\u0E35\u0E22\u0E19\u0E44\u0E27\u0E49\u0E25\u0E48\u0E27\u0E07\u0E2B\u0E19\u0E49\u0E32 \u0E44\u0E04\u0E25\u0E40\u0E2D\u0E47\u0E19\u0E15\u0E4C\u0E0B\u0E35\u0E40\u0E04\u0E23\u0E47\u0E15\u0E08\u0E30\u0E16\u0E39\u0E01\u0E08\u0E31\u0E14\u0E40\u0E01\u0E47\u0E1A\u0E44\u0E27\u0E49\u0E43\u0E19\u0E44\u0E1F\u0E25\u0E4C\u0E01\u0E32\u0E23\u0E01\u0E33\u0E2B\u0E19\u0E14\u0E04\u0E48\u0E32 Kilo \u0E02\u0E2D\u0E07\u0E04\u0E38\u0E13",
      "settings.agentBehaviour.editMcp.oauth.mode": "\u0E42\u0E2B\u0E21\u0E14",
