      "settings.agentBehaviour.instructionFiles": "\u0E44\u0E1F\u0E25\u0E4C\u0E04\u0E33\u0E2A\u0E31\u0E48\u0E07\u0E40\u0E1E\u0E34\u0E48\u0E21\u0E40\u0E15\u0E34\u0E21",
