      "agentManager.intro.stage1.title": "repository \u0E02\u0E2D\u0E07\u0E04\u0E38\u0E13",
      "agentManager.intro.stage1.text": "\u0E44\u0E1F\u0E25\u0E4C\u0E43\u0E19\u0E40\u0E04\u0E23\u0E37\u0E48\u0E2D\u0E07\u0E08\u0E30\u0E44\u0E21\u0E48\u0E40\u0E1B\u0E25\u0E35\u0E48\u0E22\u0E19\u0E41\u0E1B\u0E25\u0E07",
