      "prompt.action.autoApprove.disable": "\u0412\u0438\u043C\u043A\u043D\u0443\u0442\u0438 \u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u043D\u0435 \u0441\u0445\u0432\u0430\u043B\u0435\u043D\u043D\u044F",
      "prompt.action.autoApprove.enabled": "\u0410\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u043D\u0435 \u0441\u0445\u0432\u0430\u043B\u0435\u043D\u043D\u044F \u0443\u0432\u0456\u043C\u043A\u043D\u0435\u043D\u043E. \u0417\u0430\u043F\u0438\u0442\u0438 \u0434\u043E\u0437\u0432\u043E\u043B\u0456\u0432 \u0441\u0445\u0432\u0430\u043B\u044E\u0432\u0430\u0442\u0438\u043C\u0443\u0442\u044C\u0441\u044F \u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u043D\u043E.",
      "prompt.action.autoApprove.disabled": "\u0410\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u043D\u0435 \u0441\u0445\u0432\u0430\u043B\u0435\u043D\u043D\u044F \u0432\u0438\u043C\u043A\u043D\u0435\u043D\u043E. \u041D\u0430\u0442\u0438\u0441\u043D\u0456\u0442\u044C, \u0449\u043E\u0431 \u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u043D\u043E \u0441\u0445\u0432\u0430\u043B\u044E\u0432\u0430\u0442\u0438 \u0437\u0430\u043F\u0438\u0442\u0438 \u0434\u043E\u0437\u0432\u043E\u043B\u0456\u0432.",
      "prompt.action.autoApprove.sandboxExcluded": "\u0417\u0430\u043F\u0438\u0442\u0438 \u043D\u0430 \u0432\u0438\u0445\u0456\u0434 \u0456\u0437 \u043F\u0456\u0441\u043E\u0447\u043D\u0438\u0446\u0456 \u0437\u0430\u0432\u0436\u0434\u0438 \u0432\u0438\u043A\u043B\u044E\u0447\u0435\u043D\u043E.",
      "prompt.action.enhanceDescription": "\u041A\u043D\u043E\u043F\u043A\u0430 '\u041F\u043E\u043A\u0440\u0430\u0449\u0438\u0442\u0438 \u0437\u0430\u043F\u0438\u0442' \u0434\u043E\u043F\u043E\u043C\u0430\u0433\u0430\u0454 \u0432\u0434\u043E\u0441\u043A\u043E\u043D\u0430\u043B\u0438\u0442\u0438 \u0432\u0430\u0448 \u0437\u0430\u043F\u0438\u0442, \u043D\u0430\u0434\u0430\u044E\u0447\u0438 \u0434\u043E\u0434\u0430\u0442\u043A\u043E\u0432\u0438\u0439 \u043A\u043E\u043D\u0442\u0435\u043A\u0441\u0442, \u0443\u0442\u043E\u0447\u043D\u0435\u043D\u043D\u044F \u0430\u0431\u043E \u043F\u0435\u0440\u0435\u0444\u0440\u0430\u0437\u0443\u0432\u0430\u043D\u043D\u044F. \u0412\u0432\u0435\u0434\u0456\u0442\u044C \u0437\u0430\u043F\u0438\u0442 \u0442\u0443\u0442 \u0456 \u043D\u0430\u0442\u0438\u0441\u043D\u0456\u0442\u044C \u043A\u043D\u043E\u043F\u043A\u0443 \u0449\u0435 \u0440\u0430\u0437, \u0449\u043E\u0431 \u043F\u043E\u0431\u0430\u0447\u0438\u0442\u0438, \u044F\u043A \u0446\u0435 \u043F\u0440\u0430\u0446\u044E\u0454.",
      "prompt.action.sandbox.enable": "\u0423\u0432\u0456\u043C\u043A\u043D\u0443\u0442\u0438 \u043F\u0456\u0441\u043E\u0447\u043D\u0438\u0446\u044E",
      "prompt.action.sandbox.disable": "\u0412\u0438\u043C\u043A\u043D\u0443\u0442\u0438 \u043F\u0456\u0441\u043E\u0447\u043D\u0438\u0446\u044E",
      "prompt.action.sandbox.enabled": "\u041F\u0456\u0441\u043E\u0447\u043D\u0438\u0446\u044E \u0443\u0432\u0456\u043C\u043A\u043D\u0435\u043D\u043E. \u041A\u043E\u043C\u0430\u043D\u0434\u0438 \u043E\u0431\u043E\u043B\u043E\u043D\u043A\u0438 \u0430\u0433\u0435\u043D\u0442\u0430 \u043E\u0431\u043C\u0435\u0436\u0435\u043D\u0456 \u043A\u0430\u0442\u0430\u043B\u043E\u0433\u0430\u043C\u0438 \u043F\u0440\u043E\u0454\u043A\u0442\u0443 \u0442\u0430 Kilo.",
      "prompt.action.sandbox.disabled": "\u041F\u0456\u0441\u043E\u0447\u043D\u0438\u0446\u044E \u0432\u0438\u043C\u043A\u043D\u0435\u043D\u043E. \u041D\u0430\u0442\u0438\u0441\u043D\u0456\u0442\u044C, \u0449\u043E\u0431 \u043E\u0431\u043C\u0435\u0436\u0438\u0442\u0438 \u0437\u0430\u043F\u0438\u0441 \u043A\u043E\u043C\u0430\u043D\u0434 \u043E\u0431\u043E\u043B\u043E\u043D\u043A\u0438 \u0430\u0433\u0435\u043D\u0442\u0430 \u043A\u0430\u0442\u0430\u043B\u043E\u0433\u0430\u043C\u0438 \u043F\u0440\u043E\u0454\u043A\u0442\u0443 \u0442\u0430 Kilo.",
