      "prompt.action.sandbox.status.disabled": "\u041F\u0456\u0441\u043E\u0447\u043D\u0438\u0446\u044E \u0432\u0438\u043C\u043A\u043D\u0435\u043D\u043E",
      "prompt.action.sandbox.filesystem": "\u0424\u0430\u0439\u043B\u043E\u0432\u0430 \u0441\u0438\u0441\u0442\u0435\u043C\u0430",
