      "settings.indexing.showButton.description": "\u041F\u043E\u043A\u0430\u0437\u0443\u0432\u0430\u0442\u0438 \u043A\u043D\u043E\u043F\u043A\u0443 \u0456\u043D\u0434\u0435\u043A\u0441\u0443\u0432\u0430\u043D\u043D\u044F \u043F\u0456\u0434 \u043F\u043E\u043B\u0435\u043C \u0432\u0432\u0435\u0434\u0435\u043D\u043D\u044F, \u043F\u043E\u043A\u0438 \u0456\u043D\u0434\u0435\u043A\u0441\u0443\u0432\u0430\u043D\u043D\u044F \u0432\u0438\u043C\u043A\u043D\u0435\u043D\u043E. \u042F\u043A\u0449\u043E \u043A\u043D\u043E\u043F\u043A\u0443 \u043F\u0440\u0438\u0445\u043E\u0432\u0430\u043D\u043E, \u0432\u0456\u0434\u043A\u0440\u0438\u0439\u0442\u0435 \xAB\u041D\u0430\u043B\u0430\u0448\u0442\u0443\u0432\u0430\u043D\u043D\u044F > \u0406\u043D\u0434\u0435\u043A\u0441\u0443\u0432\u0430\u043D\u043D\u044F\xBB, \u0449\u043E\u0431 \u0443\u0432\u0456\u043C\u043A\u043D\u0443\u0442\u0438 \u0456\u043D\u0434\u0435\u043A\u0441\u0443\u0432\u0430\u043D\u043D\u044F.",
