      "settings.indexing.globalEnable.description": "\u0423\u0432\u0456\u043C\u043A\u043D\u0443\u0442\u0438 \u0456\u043D\u0434\u0435\u043A\u0441\u0443\u0432\u0430\u043D\u043D\u044F \u0434\u043B\u044F \u043A\u043E\u0436\u043D\u043E\u0433\u043E \u0440\u043E\u0431\u043E\u0447\u043E\u0433\u043E \u043F\u0440\u043E\u0441\u0442\u043E\u0440\u0443.",
