      "settings.indexing.tuning.description": "\u0420\u043E\u0437\u0448\u0438\u0440\u0435\u043D\u0438\u0439 \u043F\u0430\u0440\u0430\u043C\u0435\u0442\u0440 \u043F\u043E\u0448\u0443\u043A\u0443 \u0442\u0430 \u043F\u0430\u043A\u0435\u0442\u043D\u043E\u0457 \u043E\u0431\u0440\u043E\u0431\u043A\u0438.",
      "settings.experimental.title": "\u0415\u043A\u0441\u043F\u0435\u0440\u0438\u043C\u0435\u043D\u0442\u0430\u043B\u044C\u043D\u0435",
      "settings.language.title": "\u041C\u043E\u0432\u0430",
      "settings.aboutKiloCode.title": "\u041F\u0440\u043E Kilo Code",
      "session.messages.welcome": "Kilo Code \u2014 \u0446\u0435 \u0430\u0441\u0438\u0441\u0442\u0435\u043D\u0442 \u0437 \u043A\u043E\u0434\u0443\u0432\u0430\u043D\u043D\u044F \u043D\u0430 \u0431\u0430\u0437\u0456 \u0428\u0406. \u041F\u043E\u043F\u0440\u043E\u0441\u0456\u0442\u044C \u0439\u043E\u0433\u043E \u0440\u043E\u0437\u0440\u043E\u0431\u0438\u0442\u0438 \u0444\u0443\u043D\u043A\u0446\u0456\u044E, \u0432\u0438\u043F\u0440\u0430\u0432\u0438\u0442\u0438 \u043F\u043E\u043C\u0438\u043B\u043A\u0443 \u0430\u0431\u043E \u043F\u043E\u044F\u0441\u043D\u0438\u0442\u0438 \u0432\u0430\u0448\u0443 \u043A\u043E\u0434\u043E\u0432\u0443 \u0431\u0430\u0437\u0443.",
      "session.workspaceScope.description": "\u0427\u0430\u0442 Kilo \u0432\u0438\u043A\u043E\u0440\u0438\u0441\u0442\u043E\u0432\u0443\u0454 \u043B\u0438\u0448\u0435 \xAB{{folder}}\xBB \u2014 \u043F\u0435\u0440\u0448\u0443 \u043F\u0430\u043F\u043A\u0443 \u0432 \u0446\u044C\u043E\u043C\u0443 \u0440\u043E\u0431\u043E\u0447\u043E\u043C\u0443 \u043F\u0440\u043E\u0441\u0442\u043E\u0440\u0456.",
      "session.workspaceScope.alternatives": "\u0429\u043E\u0431 \u043F\u0440\u0430\u0446\u044E\u0432\u0430\u0442\u0438 \u0437 \u0456\u043D\u0448\u043E\u044E \u043F\u0430\u043F\u043A\u043E\u044E, \u0432\u0456\u0434\u043A\u0440\u0438\u0439\u0442\u0435 \u0457\u0457 \u0432 \u043E\u043A\u0440\u0435\u043C\u043E\u043C\u0443 \u0432\u0456\u043A\u043D\u0456 \u0430\u0431\u043E \u0434\u043E\u0434\u0430\u0439\u0442\u0435 \u044F\u043A \u043F\u0440\u043E\u0454\u043A\u0442 \u0434\u043E Agent Manager.",
