      "settings.agentBehaviour.subtab.workflows": "\u0420\u043E\u0431\u043E\u0447\u0456 \u043F\u0440\u043E\u0446\u0435\u0441\u0438",
      "settings.agentBehaviour.subtab.skills": "\u041D\u0430\u0432\u0438\u0447\u043A\u0438",
      "settings.browser.description": "\u041D\u0430\u043B\u0430\u0448\u0442\u0443\u0439\u0442\u0435 \u0432\u0431\u0443\u0434\u043E\u0432\u0430\u043D\u0443 \u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0437\u0430\u0446\u0456\u044E \u0431\u0440\u0430\u0443\u0437\u0435\u0440\u0430 \u043D\u0430 \u043E\u0441\u043D\u043E\u0432\u0456 Playwright. Kilo \u043C\u043E\u0436\u0435 \u043F\u0435\u0440\u0435\u0445\u043E\u0434\u0438\u0442\u0438 \u0432\u0435\u0431-\u0441\u0442\u043E\u0440\u0456\u043D\u043A\u0430\u043C\u0438, \u0432\u0437\u0430\u0454\u043C\u043E\u0434\u0456\u044F\u0442\u0438 \u0437 \u043D\u0438\u043C\u0438 \u0442\u0430 \u0440\u043E\u0431\u0438\u0442\u0438 \u0437\u043D\u0456\u043C\u043A\u0438 \u0435\u043A\u0440\u0430\u043D\u0430 \u0443 \u0432\u0430\u0448\u0438\u0445 \u0441\u0435\u0441\u0456\u044F\u0445.",
