      "settings.agentBehaviour.addMcp.args.help": "\u041E\u0434\u0438\u043D \u0430\u0440\u0433\u0443\u043C\u0435\u043D\u0442 \u043D\u0430 \u0440\u044F\u0434\u043E\u043A. \u0428\u043B\u044F\u0445\u0438 \u0437 \u043F\u0440\u043E\u0431\u0456\u043B\u0430\u043C\u0438 \u0437\u0431\u0435\u0440\u0456\u0433\u0430\u044E\u0442\u044C\u0441\u044F \u044F\u043A \u0454.",
