      "settings.agentBehaviour.mcp.timeout.startup.title": "\u0427\u0430\u0441 \u043E\u0447\u0456\u043A\u0443\u0432\u0430\u043D\u043D\u044F \u0437\u0430\u043F\u0443\u0441\u043A\u0443 (\u043C\u0441)",
