      "settings.display.reasoningDisplay.title": "\u0411\u043B\u043E\u043A\u0438 \u043C\u0456\u0440\u043A\u0443\u0432\u0430\u043D\u044C",
      "settings.display.reasoningDisplay.description": "\u0412\u0438\u0431\u0435\u0440\u0456\u0442\u044C, \u044F\u043A \u043F\u043E\u0447\u0438\u043D\u0430\u044E\u0442\u044C\u0441\u044F \u0431\u043B\u043E\u043A\u0438 \u043C\u0456\u0440\u043A\u0443\u0432\u0430\u043D\u044C. \u0420\u043E\u0437\u0433\u043E\u0440\u043D\u0443\u0442\u0456 \u043F\u043E\u043A\u0430\u0437\u0443\u0454 \u043F\u043E\u0432\u043D\u0438\u0439 \u0442\u0435\u043A\u0441\u0442, \u041F\u043E\u043F\u0435\u0440\u0435\u0434\u043D\u0456\u0439 \u043F\u0435\u0440\u0435\u0433\u043B\u044F\u0434 \u043E\u0431\u043C\u0435\u0436\u0443\u0454 \u0439\u043E\u0433\u043E \u043A\u043E\u0440\u043E\u0442\u043A\u0438\u043C \u043F\u0440\u043E\u043A\u0440\u0443\u0447\u0443\u0432\u0430\u043D\u0438\u043C \u043F\u0435\u0440\u0435\u0433\u043B\u044F\u0434\u043E\u043C, \u0430 \u0417\u0430\u0433\u043E\u043B\u043E\u0432\u043E\u043A \u043F\u043E\u043A\u0430\u0437\u0443\u0454 \u043B\u0438\u0448\u0435 \u0437\u0430\u0433\u043E\u043B\u043E\u0432\u043E\u043A \u0442\u0430 \u0456\u043D\u0434\u0438\u043A\u0430\u0442\u043E\u0440 \u043F\u043E\u0442\u043E\u043A\u043E\u0432\u043E\u0433\u043E \u043F\u0435\u0440\u0435\u0434\u0430\u0432\u0430\u043D\u043D\u044F, \u0434\u043E\u043A\u0438 \u0432\u0438 \u043D\u0435 \u0432\u0456\u0434\u043A\u0440\u0438\u0454\u0442\u0435 \u0439\u043E\u0433\u043E.",
