      "settings.agentBehaviour.editMode": "\u0420\u0435\u0434\u0430\u0433\u0443\u0432\u0430\u0442\u0438 \u0440\u0435\u0436\u0438\u043C",
      "settings.agentBehaviour.editMode.back": "\u041D\u0430\u0437\u0430\u0434 \u0434\u043E \u0441\u043F\u0438\u0441\u043A\u0443",
      "settings.agentBehaviour.editMode.description": "\u041E\u043F\u0438\u0441",
      "settings.agentBehaviour.editMode.native": "\u0426\u0435 \u0432\u0431\u0443\u0434\u043E\u0432\u0430\u043D\u0438\u0439 \u0440\u0435\u0436\u0438\u043C. \u0419\u043E\u0433\u043E \u0431\u0430\u0437\u043E\u0432\u0435 \u0432\u0438\u0437\u043D\u0430\u0447\u0435\u043D\u043D\u044F \u043D\u0435\u043C\u043E\u0436\u043B\u0438\u0432\u043E \u0437\u043C\u0456\u043D\u0438\u0442\u0438, \u0430\u043B\u0435 \u0432\u0438 \u043C\u043E\u0436\u0435\u0442\u0435 \u043D\u0430\u043B\u0430\u0448\u0442\u0443\u0432\u0430\u0442\u0438 \u043F\u0435\u0440\u0435\u0432\u0438\u0437\u043D\u0430\u0447\u0435\u043D\u043D\u044F \u043D\u0438\u0436\u0447\u0435.",
      "settings.agentBehaviour.editMode.prompt": "\u0421\u0438\u0441\u0442\u0435\u043C\u043D\u0438\u0439 \u0437\u0430\u043F\u0438\u0442",
      "settings.agentBehaviour.editMode.promptOverride": "\u0412\u043B\u0430\u0441\u043D\u0435 \u043F\u0435\u0440\u0435\u0432\u0438\u0437\u043D\u0430\u0447\u0435\u043D\u043D\u044F \u0441\u0438\u0441\u0442\u0435\u043C\u043D\u043E\u0433\u043E \u0437\u0430\u043F\u0438\u0442\u0443 \u0434\u043B\u044F \u0446\u044C\u043E\u0433\u043E \u0432\u0431\u0443\u0434\u043E\u0432\u0430\u043D\u043E\u0433\u043E \u0440\u0435\u0436\u0438\u043C\u0443",
      "settings.agentBehaviour.badge.subagent": "\u0441\u0443\u0431\u0430\u0433\u0435\u043D\u0442",
      "settings.agentBehaviour.perAgentPermissions.title": "\u0414\u043E\u0437\u0432\u043E\u043B\u0438 \u0434\u043B\u044F \u043A\u043E\u0436\u043D\u043E\u0433\u043E \u0430\u0433\u0435\u043D\u0442\u0430",
      "settings.agentBehaviour.perAgentPermissions.description": "\u0426\u0456 \u043D\u0430\u043B\u0430\u0448\u0442\u0443\u0432\u0430\u043D\u043D\u044F \u0437\u0430\u0441\u0442\u043E\u0441\u043E\u0432\u0443\u044E\u0442\u044C\u0441\u044F \u043B\u0438\u0448\u0435 \u0434\u043E \u0446\u044C\u043E\u0433\u043E \u043A\u043E\u0440\u0438\u0441\u0442\u0443\u0432\u0430\u0446\u044C\u043A\u043E\u0433\u043E \u0430\u0433\u0435\u043D\u0442\u0430. \u0417\u043C\u0456\u043D\u0456\u0442\u044C \u0437\u043D\u0430\u0447\u0435\u043D\u043D\u044F '\u0417\u0430 \u0437\u0430\u043C\u043E\u0432\u0447\u0443\u0432\u0430\u043D\u043D\u044F\u043C' \u0443 \u0440\u043E\u0437\u043A\u0440\u0438\u0432\u043D\u043E\u043C\u0443 \u0441\u043F\u0438\u0441\u043A\u0443, \u0449\u043E\u0431 \u0441\u0442\u0432\u043E\u0440\u0438\u0442\u0438 \u043F\u0435\u0440\u0435\u0432\u0438\u0437\u043D\u0430\u0447\u0435\u043D\u043D\u044F, \u0430\u0431\u043E \u0441\u043A\u043E\u0440\u0438\u0441\u0442\u0430\u0439\u0442\u0435\u0441\u044F \u043A\u043D\u043E\u043F\u043A\u0430\u043C\u0438 '\u0414\u043E\u0434\u0430\u0442\u0438 \u0448\u043B\u044F\u0445' \u0447\u0438 '\u0414\u043E\u0434\u0430\u0442\u0438 \u043A\u043E\u043C\u0430\u043D\u0434\u0443' \u0434\u043B\u044F \u0432\u0438\u043D\u044F\u0442\u043A\u0456\u0432 \u043E\u043A\u0440\u0435\u043C\u0438\u0445 \u0456\u043D\u0441\u0442\u0440\u0443\u043C\u0435\u043D\u0442\u0456\u0432.",
      "settings.agentBehaviour.permissions.title": "\u041E\u0431\u0447\u0438\u0441\u043B\u0435\u043D\u0456 \u0434\u043E\u0437\u0432\u043E\u043B\u0438",
