      "settings.experimental.browserAutomation.title": "\u0412\u0431\u0443\u0434\u043E\u0432\u0430\u043D\u0438\u0439 \u0431\u0440\u0430\u0443\u0437\u0435\u0440",
      "settings.experimental.browserAutomation.description": "\u041F\u043E\u043A\u0430\u0437\u0443\u0439\u0442\u0435 \u043F\u043E\u043F\u0435\u0440\u0435\u0434\u043D\u0456\u0439 \u043F\u0435\u0440\u0435\u0433\u043B\u044F\u0434 \u043B\u043E\u043A\u0430\u043B\u044C\u043D\u0438\u0445 \u0437\u0430\u0441\u0442\u043E\u0441\u0443\u043D\u043A\u0456\u0432 \u0432 Agent Manager \u0456 \u043D\u0430\u0434\u0430\u0432\u0430\u0439\u0442\u0435 \u0456\u043D\u0441\u0442\u0440\u0443\u043C\u0435\u043D\u0442 browser_open \u0441\u0435\u0441\u0456\u044F\u043C Agent Manager.",
      "settings.experimental.browserAutomation.systemChrome.title": "\u0412\u0438\u043A\u043E\u0440\u0438\u0441\u0442\u043E\u0432\u0443\u0432\u0430\u0442\u0438 \u0441\u0438\u0441\u0442\u0435\u043C\u043D\u0438\u0439 Chrome",
      "settings.experimental.browserAutomation.systemChrome.description": "\u0412\u0438\u043A\u043E\u0440\u0438\u0441\u0442\u043E\u0432\u0443\u0432\u0430\u0442\u0438 \u0432\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0439 Google Chrome \u0434\u043B\u044F \u0432\u0431\u0443\u0434\u043E\u0432\u0430\u043D\u043E\u0433\u043E \u0431\u0440\u0430\u0443\u0437\u0435\u0440\u0430. \u0412\u0438\u043C\u043A\u043D\u0456\u0442\u044C \u043B\u0438\u0448\u0435 \u044F\u043A\u0449\u043E \u0441\u0443\u043C\u0456\u0441\u043D\u0438\u0439 \u0431\u0440\u0430\u0443\u0437\u0435\u0440 Playwright Chromium \u0443\u0436\u0435 \u0432\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u043E.",
