      "marketplace.install.about.agent": "\u0410\u0433\u0435\u043D\u0442 \u0434\u043E\u0434\u0430\u0454 \u0431\u0430\u0433\u0430\u0442\u043E\u0440\u0430\u0437\u043E\u0432\u0443 \u0440\u043E\u043B\u044C \u0456\u0437 \u0432\u043B\u0430\u0441\u043D\u0438\u043C\u0438 \u0456\u043D\u0441\u0442\u0440\u0443\u043A\u0446\u0456\u044F\u043C\u0438 \u0442\u0430 \u0434\u043E\u0437\u0432\u043E\u043B\u0430\u043C\u0438.",
      "marketplace.install.about.skill": "\u041D\u0430\u0432\u0438\u0447\u043A\u0430 \u0434\u043E\u0434\u0430\u0454 \u0456\u043D\u0441\u0442\u0440\u0443\u043A\u0446\u0456\u0457 \u0442\u0430 \u0440\u0435\u0441\u0443\u0440\u0441\u0438 \u0434\u043B\u044F \u043F\u0435\u0432\u043D\u0438\u0445 \u0437\u0430\u0432\u0434\u0430\u043D\u044C, \u044F\u043A\u0456 Kilo \u043C\u043E\u0436\u0435 \u0437\u0430\u0432\u0430\u043D\u0442\u0430\u0436\u0438\u0442\u0438 \u0437\u0430 \u043F\u043E\u0442\u0440\u0435\u0431\u0438.",
      "marketplace.install.mcp.warning": "MCP-\u0441\u0435\u0440\u0432\u0435\u0440\u0438 \u043C\u043E\u0436\u0443\u0442\u044C \u0432\u0438\u043A\u043E\u043D\u0443\u0432\u0430\u0442\u0438 \u043B\u043E\u043A\u0430\u043B\u044C\u043D\u0456 \u043A\u043E\u043C\u0430\u043D\u0434\u0438 \u0430\u0431\u043E \u043F\u0456\u0434\u043A\u043B\u044E\u0447\u0430\u0442\u0438\u0441\u044F \u0434\u043E \u0437\u043E\u0432\u043D\u0456\u0448\u043D\u0456\u0445 \u0441\u0435\u0440\u0432\u0456\u0441\u0456\u0432. Kilo \u0437\u0430\u043F\u0438\u0442\u0430\u0454 \u0434\u043E\u0437\u0432\u0456\u043B \u043F\u0435\u0440\u0435\u0434 \u0432\u0438\u043A\u043E\u0440\u0438\u0441\u0442\u0430\u043D\u043D\u044F\u043C \u0457\u0445\u043D\u0456\u0445 \u0456\u043D\u0441\u0442\u0440\u0443\u043C\u0435\u043D\u0442\u0456\u0432, \u044F\u043A\u0449\u043E \u0432\u0430\u0448\u0456 \u0434\u043E\u0437\u0432\u043E\u043B\u0438 \u043D\u0435 \u0434\u0430\u044E\u0442\u044C \u0437\u043C\u043E\u0433\u0438 \u0440\u043E\u0431\u0438\u0442\u0438 \u0446\u0435 \u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u043D\u043E.",
      "marketplace.install.project.warning": "\u0424\u0430\u0439\u043B\u0438 \u043F\u0440\u043E\u0454\u043A\u0442\u0443 \u043C\u043E\u0436\u0443\u0442\u044C \u0431\u0443\u0442\u0438 \u0434\u043E\u0434\u0430\u043D\u0456 \u0434\u043E \u0441\u0438\u0441\u0442\u0435\u043C\u0438 \u043A\u043E\u043D\u0442\u0440\u043E\u043B\u044E \u0432\u0435\u0440\u0441\u0456\u0439. \u041D\u0435 \u0437\u0431\u0435\u0440\u0456\u0433\u0430\u0439\u0442\u0435 \u0442\u0443\u0442 \u0441\u0435\u043A\u0440\u0435\u0442\u0438, \u044F\u043A\u0449\u043E \u043A\u043E\u043D\u0444\u0456\u0433\u0443\u0440\u0430\u0446\u0456\u044F \u043D\u0435 \u043F\u043E\u0441\u0438\u043B\u0430\u0454\u0442\u044C\u0441\u044F \u043D\u0430 \u0437\u043C\u0456\u043D\u043D\u0443 \u0441\u0435\u0440\u0435\u0434\u043E\u0432\u0438\u0449\u0430.",
      "marketplace.install.learnMore": "\u0414\u0456\u0437\u043D\u0430\u0439\u0442\u0435\u0441\u044F, \u044F\u043A \u043F\u0440\u0430\u0446\u044E\u0454 \u0432\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u043D\u044F \u0437 Marketplace",
      "marketplace.install.learnMcp": "\u0414\u043E\u043A\u043B\u0430\u0434\u043D\u0456\u0448\u0435 \u043F\u0440\u043E MCP",
      "marketplace.install.about.plugin": "\u041F\u043B\u0430\u0433\u0456\u043D \u0434\u043E\u0434\u0430\u0454 \u0434\u043E Kilo \u043A\u043E\u0440\u0438\u0441\u0442\u0443\u0432\u0430\u0446\u044C\u043A\u0456 \u0456\u043D\u0441\u0442\u0440\u0443\u043C\u0435\u043D\u0442\u0438 \u0442\u0430 \u0456\u043D\u0442\u0435\u0433\u0440\u0430\u0446\u0456\u0457. \u041F\u043B\u0430\u0433\u0456\u043D\u0438 \u0432\u0438\u043A\u043E\u043D\u0443\u044E\u0442\u044C\u0441\u044F \u0437 \u043F\u043E\u0432\u043D\u0438\u043C\u0438 \u043F\u0440\u0430\u0432\u0430\u043C\u0438 \u0434\u043E\u0441\u0442\u0443\u043F\u0443.",
      "marketplace.install.plugin.warning": "\u041F\u043B\u0430\u0433\u0456\u043D\u0438 \u0432\u0438\u043A\u043E\u043D\u0443\u044E\u0442\u044C \u043A\u043E\u0434 \u0456\u0437 \u043F\u043E\u0432\u043D\u0438\u043C\u0438 \u043F\u0440\u0430\u0432\u0430\u043C\u0438 \u0434\u043E\u0441\u0442\u0443\u043F\u0443. \u0412\u043E\u043D\u0438 \u043C\u043E\u0436\u0443\u0442\u044C \u0447\u0438\u0442\u0430\u0442\u0438 \u0439 \u0437\u043C\u0456\u043D\u044E\u0432\u0430\u0442\u0438 \u0432\u0430\u0448\u0456 \u0444\u0430\u0439\u043B\u0438, \u0432\u0438\u043A\u043E\u043D\u0443\u0432\u0430\u0442\u0438 \u043A\u043E\u043C\u0430\u043D\u0434\u0438 \u0442\u0430 \u043E\u0442\u0440\u0438\u043C\u0443\u0432\u0430\u0442\u0438 \u0434\u043E\u0441\u0442\u0443\u043F \u0434\u043E \u0432\u0430\u0448\u0438\u0445 \u043E\u0431\u043B\u0456\u043A\u043E\u0432\u0438\u0445 \u0434\u0430\u043D\u0438\u0445 \u0456 \u043C\u0435\u0440\u0435\u0436\u0456. \u0412\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u044E\u0439\u0442\u0435 \u043B\u0438\u0448\u0435 \u043F\u043B\u0430\u0433\u0456\u043D\u0438, \u044F\u043A\u0438\u043C \u0434\u043E\u0432\u0456\u0440\u044F\u0454\u0442\u0435.",
      "marketplace.intro": "\u0412\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u044E\u0439\u0442\u0435 \u0431\u0430\u0433\u0430\u0442\u043E\u0440\u0430\u0437\u043E\u0432\u0438\u0445 \u0430\u0433\u0435\u043D\u0442\u0456\u0432, \u043D\u0430\u0432\u0438\u0447\u043A\u0438, \u0456\u043D\u0441\u0442\u0440\u0443\u043C\u0435\u043D\u0442\u0438 MCP \u0442\u0430 \u043F\u043B\u0430\u0433\u0456\u043D\u0438 \u0434\u043B\u044F \u043E\u0434\u043D\u043E\u0433\u043E \u0430\u0431\u043E \u0432\u0441\u0456\u0445 \u043F\u0440\u043E\u0454\u043A\u0442\u0456\u0432.",
