      "marketplace.remove.mcp.skills": "\u0426\u0435 \u0442\u0430\u043A\u043E\u0436 \u0432\u0438\u0434\u0430\u043B\u0438\u0442\u044C \u0441\u0443\u043F\u0443\u0442\u043D\u0456 \u043D\u0430\u0432\u0438\u0447\u043A\u0438, \u0449\u043E \u043D\u0430\u043B\u0435\u0436\u0430\u0442\u044C \u0446\u044C\u043E\u043C\u0443 \u0432\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u043D\u044E. \u041D\u0435\u0437\u0430\u043B\u0435\u0436\u043D\u043E \u0432\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u0456 \u043D\u0430\u0432\u0438\u0447\u043A\u0438 \u0431\u0443\u0434\u0435 \u0437\u0431\u0435\u0440\u0435\u0436\u0435\u043D\u043E.",
