      "agentManager.settings.autoBranchNaming.description": "\u0410\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u043D\u043E \u0456\u043C\u0435\u043D\u0443\u0432\u0430\u0442\u0438 \u0433\u0456\u043B\u043A\u0438, \u043A\u043E\u043B\u0438 \u0440\u043E\u0437\u043C\u043E\u0432\u0430 \u043E\u043F\u0438\u0441\u0443\u0454 \u0447\u0456\u0442\u043A\u0435 \u0437\u0430\u0432\u0434\u0430\u043D\u043D\u044F. \u0417\u0430\u0441\u0442\u043E\u0441\u043E\u0432\u0443\u0454\u0442\u044C\u0441\u044F \u0434\u043E \u0432\u0441\u0456\u0445 \u043F\u0440\u043E\u0454\u043A\u0442\u0456\u0432. \u0413\u0456\u043B\u043A\u0438 \u0437 \u044F\u0432\u043D\u043E \u0437\u0430\u0434\u0430\u043D\u0438\u043C\u0438 \u043D\u0430\u0437\u0432\u0430\u043C\u0438 \u0442\u0430 \u043E\u043F\u0443\u0431\u043B\u0456\u043A\u043E\u0432\u0430\u043D\u0456 \u0433\u0456\u043B\u043A\u0438 \u043D\u0456\u043A\u043E\u043B\u0438 \u043D\u0435 \u043F\u0435\u0440\u0435\u0439\u043C\u0435\u043D\u043E\u0432\u0443\u044E\u0442\u044C\u0441\u044F.",
      "agentManager.settings.branchPrefix.title": "\u041F\u0440\u0435\u0444\u0456\u043A\u0441 \u0433\u0456\u043B\u043A\u0438",
      "agentManager.settings.branchPrefix.description": "\u041F\u0440\u0435\u0444\u0456\u043A\u0441 \u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u043D\u043E \u0456\u043C\u0435\u043D\u043E\u0432\u0430\u043D\u0438\u0445 \u0433\u0456\u043B\u043E\u043A \u0443 \u0432\u0441\u0456\u0445 \u043F\u0440\u043E\u0454\u043A\u0442\u0430\u0445, \u043D\u0430\u043F\u0440\u0438\u043A\u043B\u0430\u0434 feature/. \u041D\u0435 \u0437\u0430\u0441\u0442\u043E\u0441\u043E\u0432\u0443\u0454\u0442\u044C\u0441\u044F \u0434\u043E \u044F\u0432\u043D\u043E \u0437\u0430\u0434\u0430\u043D\u0438\u0445 \u043D\u0430\u0437\u0432 \u0433\u0456\u043B\u043E\u043A. \u0417\u0430\u043B\u0438\u0448\u0442\u0435 \u043F\u043E\u0440\u043E\u0436\u043D\u0456\u043C, \u0449\u043E\u0431 \u043D\u0435 \u0432\u0438\u043A\u043E\u0440\u0438\u0441\u0442\u043E\u0432\u0443\u0432\u0430\u0442\u0438 \u043F\u0440\u0435\u0444\u0456\u043A\u0441.",
      "agentManager.settings.worktreePool.title": "\u041F\u043E\u043F\u0435\u0440\u0435\u0434\u043D\u0454 \u043F\u0440\u043E\u0433\u0440\u0456\u0432\u0430\u043D\u043D\u044F worktree",
      "agentManager.settings.worktreePool.description": "\u0413\u043E\u0442\u0443\u0432\u0430\u0442\u0438 worktree \u0437\u0430\u0437\u0434\u0430\u043B\u0435\u0433\u0456\u0434\u044C \u0443 \u0444\u043E\u043D\u043E\u0432\u043E\u043C\u0443 \u0440\u0435\u0436\u0438\u043C\u0456, \u0449\u043E\u0431 \u043D\u043E\u0432\u0456 \u0441\u0435\u0441\u0456\u0457 Agent Manager \u0437\u0430\u043F\u0443\u0441\u043A\u0430\u043B\u0438\u0441\u044F \u0448\u0432\u0438\u0434\u0448\u0435. \u0412\u0438\u043A\u043E\u0440\u0438\u0441\u0442\u043E\u0432\u0443\u0454 \u0434\u043E\u0434\u0430\u0442\u043A\u043E\u0432\u0438\u0439 \u043F\u0440\u043E\u0441\u0442\u0456\u0440 \u043D\u0430 \u0434\u0438\u0441\u043A\u0443 \u0434\u043B\u044F \u043E\u0434\u043D\u043E\u0433\u043E checkout \u043D\u0430 \u043A\u043E\u0436\u0435\u043D \u0432\u0456\u0434\u043A\u0440\u0438\u0442\u0438\u0439 \u043F\u0440\u043E\u0454\u043A\u0442.",
      "agentManager.hints.switchSession": "\u041F\u0435\u0440\u0435\u043C\u043A\u043D\u0443\u0442\u0438 \u0441\u0435\u0441\u0456\u044E",
