      "agentManager.setup.error.no_commits": "\u0423 \u0446\u044C\u043E\u043C\u0443 \u0440\u0435\u043F\u043E\u0437\u0438\u0442\u043E\u0440\u0456\u0457 \u0449\u0435 \u043D\u0435\u043C\u0430\u0454 \u043A\u043E\u043C\u043C\u0456\u0442\u0456\u0432. \u0421\u0442\u0432\u043E\u0440\u0456\u0442\u044C \u043F\u043E\u0447\u0430\u0442\u043A\u043E\u0432\u0438\u0439 \u043A\u043E\u043C\u043C\u0456\u0442 \u043F\u0435\u0440\u0435\u0434 \u0432\u0438\u043A\u043E\u0440\u0438\u0441\u0442\u0430\u043D\u043D\u044F\u043C worktrees.",
      "agentManager.setup.error.worktree_missing": "\u0422\u0435\u043A\u0438 \u0446\u044C\u043E\u0433\u043E worktree \u0431\u0456\u043B\u044C\u0448\u0435 \u043D\u0435\u043C\u0430\u0454. \u0412\u0456\u0434\u043D\u043E\u0432\u0456\u0442\u044C \u0457\u0457 \u0437 \u0433\u0456\u043B\u043A\u0438 \u0430\u0431\u043E \u0432\u0438\u043B\u0443\u0447\u0456\u0442\u044C worktree.",
      "agentManager.setup.error.worktree_unregistered": "Git \u0431\u0456\u043B\u044C\u0448\u0435 \u043D\u0435 \u0432\u0456\u0434\u0441\u043B\u0456\u0434\u043A\u043E\u0432\u0443\u0454 \u0446\u044E \u0442\u0435\u043A\u0443 \u044F\u043A worktree. \u0412\u0438\u043B\u0443\u0447\u0456\u0442\u044C \u0457\u0457 \u0442\u0430 \u0441\u0442\u0432\u043E\u0440\u0456\u0442\u044C \u043D\u043E\u0432\u0438\u0439 worktree.",
      "agentManager.setup.error.git_timeout": "Git \u043D\u0435 \u0432\u0456\u0434\u043F\u043E\u0432\u0456\u0432 \u0432\u0447\u0430\u0441\u043D\u043E. \u041F\u0435\u0440\u0435\u0432\u0456\u0440\u0442\u0435 \u0434\u043E\u0441\u0442\u0443\u043F\u043D\u0456\u0441\u0442\u044C \u0440\u0435\u043F\u043E\u0437\u0438\u0442\u043E\u0440\u0456\u044E \u0439 \u0441\u043F\u0440\u043E\u0431\u0443\u0439\u0442\u0435 \u0449\u0435 \u0440\u0430\u0437.",
